import { NextRequest, NextResponse } from "next/server";
import authService from "@/lib/auth/service";
import { db } from "@/lib/db/prisma";
import { errorTracker } from "@/lib/monitoring/error-tracker";
import { monitor } from "@/lib/monitoring/performance";

/**
 * GET /api/admin/alerts
 * Get active alerts and incidents
 * Admin only
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(decoded.userId);
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    // Get alerts
    const alerts = generateAlerts();

    return NextResponse.json(
      {
        alerts,
        count: alerts.length,
        criticalCount: alerts.filter((a) => a.severity === "critical").length,
        lastUpdated: new Date().toISOString(),
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Alerts _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

/**
 * POST /api/admin/alerts
 * Acknowledge or dismiss alerts
 * Admin only
 */
export async function POST(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(decoded.userId);
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    const body = await _request.json();
    const { action, alertId } = body;

    if (!action || !alertId) {
      return NextResponse.json(
        {
          _error: {
            message: "Missing required fields: action, alertId",
            code: "MISSING_FIELDS",
          },
        },
        { status: 400 }
      );
    }

    if (!["acknowledge", "dismiss", "escalate"].includes(action)) {
      return NextResponse.json(
        { _error: { message: "Invalid action", code: "INVALID_ACTION" } },
        { status: 400 }
      );
    }

    return NextResponse.json(
      {
        success: true,
        alertId,
        action,
        timestamp: new Date().toISOString(),
        message: `Alert ${action}d successfully`,
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Alert action _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

function generateAlerts() {
  const alerts: unknown[] = [];
  const now = new Date();
  const errorStats = errorTracker.getErrorStats();
  const metrics = monitor.getAllMetrics();

  // Check for high error rates - use error stats
  if (errorStats.total > 10) {
    alerts.push({
      id: `error_high_${now.getTime()}`,
      type: "HIGH_ERROR_RATE",
      severity: errorStats.total > 50 ? "critical" : "warning",
      component: "Application Errors",
      message: `High error rate detected: ${errorStats.total} errors logged`,
      count: errorStats.total,
      timestamp: now.toISOString(),
      actionable: true,
      suggestedAction: "Review error logs and escalate to engineering",
    });
  }

  // Check for performance degradation based on metrics
  if (metrics && metrics.length > 0) {
    const avgResponseTime =
      metrics.reduce((sum: number, m: unknown) => sum + m.duration, 0) /
      metrics.length;
    if (avgResponseTime > 1000) {
      alerts.push({
        id: `perf_response_${now.getTime()}`,
        type: "PERFORMANCE_DEGRADATION",
        severity: avgResponseTime > 5000 ? "critical" : "warning",
        component: "API Response Times",
        message: `High response times detected: avg ${Math.round(avgResponseTime)}ms`,
        responseTime: Math.round(avgResponseTime),
        timestamp: now.toISOString(),
        actionable: true,
        suggestedAction: "Check system load and optimize queries",
      });
    }
  }

  // Check memory usage
  const mem = process.memoryUsage();
  const heapPercent = (mem.heapUsed / mem.heapTotal) * 100;
  if (heapPercent > 85) {
    alerts.push({
      id: `memory_${now.getTime()}`,
      type: "HIGH_MEMORY_USAGE",
      severity: heapPercent > 95 ? "critical" : "warning",
      component: "System Memory",
      message: `High memory usage: ${Math.round(heapPercent)}% of heap`,
      heapUsedMB: Math.round(mem.heapUsed / 1024 / 1024),
      heapTotalMB: Math.round(mem.heapTotal / 1024 / 1024),
      timestamp: now.toISOString(),
      actionable: true,
      suggestedAction: "Consider garbage collection or scaling",
    });
  }

  return alerts.sort((a, b) => {
    const severityOrder = { critical: 0, warning: 1, info: 2 };
    return severityOrder[a.severity as keyof typeof severityOrder] -
      severityOrder[b.severity as keyof typeof severityOrder]
      ? -1
      : 1;
  });
}

import { NextRequest, NextResponse } from "next/server";
import authService from "@/lib/auth/service";
import { db } from "@/lib/db/prisma";

/**
 * GET /api/admin/audit-logs
 * View audit logs with filtering
 * Admin only
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.userId) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid token (missing userId)",
            code: "INVALID_TOKEN",
          },
        },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(String(decoded.userId));
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(_request.url);
    const action = searchParams.get("action");
    const userId = searchParams.get("userId");
    const resource = searchParams.get("resource");
    const startDate = searchParams.get("startDate");
    const endDate = searchParams.get("endDate");
    const skip = parseInt(searchParams.get("skip") || "0");
    const take = Math.min(parseInt(searchParams.get("take") || "50"), 100);

    // Build query filters
    const filters: Record<string, unknown> = {};

    if (action) (filters as Record<string, unknown>)["action"] = action;
    if (userId) (filters as Record<string, unknown>)["userId"] = userId;
    if (resource) (filters as Record<string, unknown>)["resource"] = resource;

    if (startDate || endDate) {
      const ts: Record<string, Date> = {};
      if (startDate) ts.gte = new Date(startDate);
      if (endDate) ts.lte = new Date(endDate);
      (filters as Record<string, unknown>)["timestamp"] = ts;
    }

    // Fetch audit logs
    const logs = await db.auditLog.findMany({
      where: filters,
      orderBy: { timestamp: "desc" },
      skip,
      take,
      select: {
        id: true,
        userId: true,
        action: true,
        resource: true,
        resourceId: true,
        changes: true,
        ipAddress: true,
        userAgent: true,
        timestamp: true,
      },
    });

    // Get total count
    const total = await db.auditLog.count({ where: filters });

    return NextResponse.json(
      {
        logs,
        pagination: {
          skip,
          take,
          total,
          pages: Math.ceil(total / take),
        },
        filters: {
          action,
          userId,
          resource,
          startDate,
          endDate,
        },
        timestamp: new Date().toISOString(),
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Audit logs _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

/**
 * Helper function to create audit log entry
 * Usage: Call this from other API routes to log actions
 */
export async function createAuditLog({
  userId,
  action,
  resource,
  resourceId,
  changes,
  ipAddress,
  userAgent,
}: {
  userId: string;
  action: string;
  resource: string;
  resourceId?: string;
  changes?: Record<string, unknown>;
  ipAddress?: string;
  userAgent?: string;
}) {
  try {
    return await db.auditLog.create({
      data: {
        userId,
        action,
        resource,
        resourceId,
        changes: changes ? JSON.stringify(changes) : null,
        ipAddress,
        userAgent,
        timestamp: new Date(),
      },
    });
  } catch (_error) {
    (globalThis.console as any)?.error?.("Error creating audit log:", _error);
    // Don't throw - audit logging should not break main flow
  }
}

/**
 * Audit log export endpoint
 */
export async function POST(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.userId) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid token (missing userId)",
            code: "INVALID_TOKEN",
          },
        },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(String(decoded.userId));
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    const body = (await _request.json()) as Record<string, unknown>;
    const format = (body as any).format as string;
    const filters = (body as any).filters as
      | Record<string, unknown>
      | undefined;

    if (!["csv", "json", "pdf"].includes(format)) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid format. Use csv, json, or pdf",
            code: "INVALID_FORMAT",
          },
        },
        { status: 400 }
      );
    }

    // Fetch all logs matching filters (with limit)
    const logs = await db.auditLog.findMany({
      where: filters || {},
      orderBy: { timestamp: "desc" },
      take: 10000,
    });

    let content: string;
    let filename: string;
    let contentType: string;

    if (format === "json") {
      content = JSON.stringify(logs, null, 2);
      filename = `audit-logs-${new Date().toISOString()}.json`;
      contentType = "application/json";
    } else if (format === "csv") {
      content = convertLogsToCSV(logs as any);
      filename = `audit-logs-${new Date().toISOString()}.csv`;
      contentType = "text/csv";
    } else {
      // PDF format - simplified version
      content = JSON.stringify({
        message: "PDF export not yet implemented",
        logs: logs.length,
      });
      filename = `audit-logs-${new Date().toISOString()}.json`;
      contentType = "application/json";
    }

    return new NextResponse(content, {
      status: 200,
      headers: {
        "Content-Type": contentType,
        "Content-Disposition": `attachment; filename="${filename}"`,
      },
    });
  } catch (_error) {
    (globalThis.console as any)?.error?.("Audit log export _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

function convertLogsToCSV(logs: Record<string, unknown>[]): string {
  if (logs.length === 0) return "No data";

  const headers = [
    "ID",
    "User ID",
    "Action",
    "Resource",
    "Resource ID",
    "IP Address",
    "Timestamp",
  ];
  const rows = logs.map((log) => [
    (log as any).id,
    (log as any).userId,
    (log as any).action,
    (log as any).resource,
    (log as any).resourceId || "",
    (log as any).ipAddress || "",
    (log as any).timestamp,
  ]);

  const csv = [
    headers.join(","),
    ...rows.map((row) =>
      row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ),
  ].join("\n");

  return csv;
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db/prisma";
import authService from "@/lib/auth/service";

/**
 * GET /api/admin/dashboard
 * Get admin dashboard statistics
 * Requires authentication and admin role
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    // Verify token synchronously
    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.userId) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid token (missing userId)",
            code: "INVALID_TOKEN",
          },
        },
        { status: 401 }
      );
    }

    // Check if user is admin
    const user = await db.userService.findById(String(decoded.userId));
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    // Get dashboard statistics
    const totalUsers = await db.prisma.user.count();
    const activeUsers = await db.prisma.user.count({
      where: {
        lastLogin: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
    });

    const totalTransactions = await db.prisma.transaction.count();
    const completedTransactions = await db.prisma.transaction.count({
      where: { status: "completed" },
    });

    const totalWallets = await db.prisma.wallet.count();

    // Get transaction volume
    const transactionVolume = await db.prisma.transaction.aggregate({
      where: { status: "completed" },
      _sum: { amount: true },
    });

    // Get revenue (assume 2% transaction fee)
    const revenue = (transactionVolume._sum.amount || 0) * 0.02;

    // Get top users by transaction count
    const topUsers = await db.prisma.user.findMany({
      take: 5,
      orderBy: {
        transactions: {
          _count: "desc",
        },
      },
      select: {
        id: true,
        username: true,
        email: true,
        _count: {
          select: { transactions: true },
        },
      },
    });

    return NextResponse.json(
      {
        dashboard: {
          users: {
            total: totalUsers,
            active: activeUsers,
            activePercentage: ((activeUsers / totalUsers) * 100).toFixed(2),
          },
          transactions: {
            total: totalTransactions,
            completed: completedTransactions,
            completionRate: (
              (completedTransactions / totalTransactions) *
              100
            ).toFixed(2),
          },
          wallets: {
            total: totalWallets,
          },
          revenue: {
            transactionVolume: transactionVolume._sum.amount || 0,
            estimatedRevenue: revenue.toFixed(2),
          },
          topUsers: topUsers.map((u) => ({
            id: u.id,
            username: u.username,
            email: u.email,
            transactionCount: u._count?.transactions || 0,
          })),
        },
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Dashboard _error:", _error);
    return NextResponse.json(
