function calculateHealthScore(monitoring: Record<string, unknown>): number {
  let score = 100;

  // Check memory usage (safe access)
  const system = monitoring["system"] as Record<string, unknown> | undefined;
  const memory = system
    ? (system["memory"] as { heapUsed?: number } | undefined)
    : undefined;
  const heapUsed = memory?.heapUsed;
  if (typeof heapUsed === "number") {
    const heapUsedMB = Math.round(heapUsed / 1024 / 1024);
    if (heapUsedMB > 500) {
      score -= 10; // High memory usage
    }
  }

  // Check errors
  const errorsObj = (monitoring["errors"] as Record<string, unknown>) || {};
  const totalErrors = (
    Object.values(errorsObj as Record<string, { count?: number }>) as Array<{
      count?: number;
    }>
  ).reduce(
    (sum: number, _err: { count?: number }) => sum + (Number(_err.count) || 0),
    0
  );
  if (totalErrors > 10) {
    score -= Math.min(30, totalErrors);
  }

  // Check performance
  type PerfMetric = { successRate?: string | number } & Record<string, unknown>;
  const perfObj = (monitoring["performance"] as Record<string, unknown>) || {};
  const metrics: PerfMetric[] = Object.values(perfObj) as PerfMetric[];
  const failedMetrics = metrics.filter((m: PerfMetric) => {
    if (!m) return false;
    const sr = m.successRate;
    const parsed = typeof sr === "string" ? parseFloat(sr) : Number(sr);
    return !Number.isNaN(parsed) && parsed < 95;
  });
  if (failedMetrics.length > 0) {
    score -= failedMetrics.length * 5;
  }

  return Math.max(0, score);
}

import { NextRequest, NextResponse } from "next/server";
import authService from "@/lib/auth/service";
import { db } from "@/lib/db/prisma";

interface RateLimit {
  userId: string;
  endpoint: string;
  windowStart: number;
  requestCount: number;
  limit: number;
}

// In-memory store for rate limits (in production, use Redis)
const rateLimits = new Map<string, RateLimit>();
const WINDOW_SIZE = 60 * 1000; // 1 minute
const DEFAULT_LIMIT = 100; // requests per minute

/**
 * GET /api/admin/rate-limits
 * View rate limit configuration and current usage
 * Admin only
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(decoded.userId);
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(_request.url);
    const userId = searchParams.get("userId");

    // Get rate limit stats
    const limits = Array.from(rateLimits.values()).filter(
      (limit) => !userId || limit.userId === userId
    );

    return NextResponse.json(
      {
        config: {
          defaultLimit: DEFAULT_LIMIT,
          windowSize: WINDOW_SIZE,
          unit: "requests per minute",
        },
        currentUsage: limits.map((limit) => ({
          userId: limit.userId,
          endpoint: limit.endpoint,
          requestCount: limit.requestCount,
          limit: limit.limit,
          percentageUsed: Math.round((limit.requestCount / limit.limit) * 100),
          status:
            limit.requestCount > limit.limit * 0.9
              ? "warning"
              : limit.requestCount > limit.limit
              ? "exceeded"
              : "normal",
        })),
        totalTrackedUsers: new Set(limits.map((l) => l.userId)).size,
        timestamp: new Date().toISOString(),
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Rate limits _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/admin/rate-limits
 * Update rate limit for specific user or endpoint
 * Admin only
 */
export async function PUT(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(decoded.userId);
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    const body = await _request.json();
    const { userId, endpoint, newLimit, action } = body;

    if (!userId || !endpoint || (!newLimit && action !== "reset")) {
      return NextResponse.json(
        {
          _error: {
            message: "Missing required fields: userId, endpoint, newLimit",
            code: "MISSING_FIELDS",
          },
        },
        { status: 400 }
      );
    }

    const key = `${userId}:${endpoint}`;

    if (action === "reset") {
      rateLimits.delete(key);
      return NextResponse.json(
        {
          success: true,
          message: "Rate limit reset",
          userId,
          endpoint,
          timestamp: new Date().toISOString(),
        },
        { status: 200 }
      );
    }

    const existing = rateLimits.get(key) || {
      userId,
      endpoint,
      windowStart: Date.now(),
      requestCount: 0,
      limit: DEFAULT_LIMIT,
    };

    existing.limit = newLimit;
    rateLimits.set(key, existing);

    return NextResponse.json(
      {
        success: true,
        message: "Rate limit updated",
        userId,
        endpoint,
        newLimit,
        timestamp: new Date().toISOString(),
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Rate limit update _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

/**
 * Middleware function to check rate limits
 * Usage: Use in API routes to enforce rate limits
 */
export function createRateLimitMiddleware(endpoint: string, limit?: number) {
  return (userId: string): boolean => {
    const key = `${userId}:${endpoint}`;
    const now = Date.now();
    let rateLimit = rateLimits.get(key);

    if (!rateLimit) {
      rateLimit = {
        userId,
        endpoint,
        windowStart: now,
        requestCount: 1,
        limit: limit || DEFAULT_LIMIT,
      };
      rateLimits.set(key, rateLimit);
      return true;
    }

    // Reset window if expired
    if (now - rateLimit.windowStart > WINDOW_SIZE) {
      rateLimit.windowStart = now;
      rateLimit.requestCount = 1;
      return true;
    }

    // Increment and check limit
    rateLimit.requestCount++;
    return rateLimit.requestCount <= rateLimit.limit;
  };
}

/**
 * Cleanup old rate limit entries periodically
 * Call this in a cron job or at server startup
 */
export function cleanupRateLimits() {
  const now = Date.now();
  let cleaned = 0;

  for (const [key, limit] of rateLimits.entries()) {
    if (now - limit.windowStart > WINDOW_SIZE * 5) {
      rateLimits.delete(key);
      cleaned++;
    }
  }

  return cleaned;
}

