/**
 * GET /api/analytics/wallets
 * Get wallet analytics and performance metrics
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.userId) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid token (missing userId)",
            code: "INVALID_TOKEN",
          },
        },
        { status: 401 }
      );
    }

    const userId = String(decoded.userId);

    // Get all user wallets
    const wallets = (await db.prisma.wallet.findMany({
      where: { userId },
      include: {
        _count: {
          select: { transactions: true },
        },
      },
    })) as Array<{
      id: string;
      currency?: unknown;
      balance?: unknown;
      createdAt?: unknown;
      status?: unknown;
      _count?: { transactions?: number };
    }>;

    // Get wallet statistics
    const stats = {
      totalWallets: wallets.length,
      totalBalance: 0,
      currencyDistribution: {} as Record<string, any>,
      walletUtilization: 0,
      transactionStats: {
        totalTransactions: 0,
        averageTransactionSize: 0,
      },
    };

    const transactionsByWallet: Record<string, any[]> = {};

    for (const wallet of wallets) {
      const bal = Number(wallet.balance ?? 0);
      stats.totalBalance += bal;

      const cur = String(wallet.currency ?? "UNKNOWN");
      if (!stats.currencyDistribution[cur]) {
        stats.currencyDistribution[cur] = {
          currency: cur,
          walletCount: 0,
          totalBalance: 0,
          averageBalance: 0,
        };
      }

      stats.currencyDistribution[cur].walletCount += 1;
      stats.currencyDistribution[cur].totalBalance += bal;

      // Get wallet transactions
      const walletTxns = (await db.prisma.transaction.findMany({
        where: { walletId: String(wallet.id) },
      })) as any[] as Array<Record<string, unknown>>;

      transactionsByWallet[String(wallet.id)] = walletTxns;
      stats.transactionStats.totalTransactions += walletTxns.length;
    }

    // Calculate averages
    Object.values(stats.currencyDistribution).forEach((dist: unknown) => {
      dist.averageBalance = dist.totalBalance / dist.walletCount;
    });

    // Calculate wallet utilization (wallets with transactions / total wallets)
    const activeWallets = Object.keys(transactionsByWallet).filter(
      (walletId) => transactionsByWallet[walletId].length > 0
    ).length;

    stats.walletUtilization =
      wallets.length > 0 ? (activeWallets / wallets.length) * 100 : 0;

    if (stats.transactionStats.totalTransactions > 0) {
      stats.transactionStats.averageTransactionSize =
        stats.totalBalance / stats.transactionStats.totalTransactions;
    }

    // Get growth metrics (last 30 days)
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const recentWallets = await db.prisma.wallet.count({
      where: {
        userId,
        createdAt: { gte: thirtyDaysAgo },
      },
    });

    const recentTransactions = await db.prisma.transaction.count({
      where: {
        wallet: { userId },
        createdAt: { gte: thirtyDaysAgo },
      },
    });

    return NextResponse.json(
      {
        analytics: {
          overview: stats,
          growth: {
            newWalletsLast30Days: recentWallets,
            transactionsLast30Days: recentTransactions,
          },
          wallets: wallets.map((w: unknown) => ({
            id: w.id,
            currency: w.currency,
            balance: w.balance,
            transactionCount: w._count?.transactions ?? 0,
            createdAt: w.createdAt,
            status: w.status,
          })),
        },
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Wallet analytics _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";

const USERS_FILE = path.resolve(process.cwd(), "data", "users.json");
const JWT_SECRET = process.env.JWT_SECRET || "changeme";

function loadUsers(): unknown[] {
  if (!fs.existsSync(USERS_FILE)) return [];
  try {
    return JSON.parse(fs.readFileSync(USERS_FILE, "utf-8"));
  } catch (_e) {
    return [];
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { username, password } = body;
    if (!username || !password) {
      return NextResponse.json({ error: "Missing fields" }, { status: 400 });
    }

    const users = loadUsers();
    const user = users.find((u: unknown) => u.username === username);
    if (!user) return NextResponse.json({ error: "Invalid credentials" }, { status: 401 });

    const valid = await bcrypt.compare(password, user.password);
    if (!valid) return NextResponse.json({ error: "Invalid credentials" }, { status: 401 });

    const token = jwt.sign({ id: user.id, username: user.username, role: user.role }, JWT_SECRET, { expiresIn: "8h" });

    return NextResponse.json({ token, user: { id: user.id, username: user.username, role: user.role } });
  } catch (error) {
    return NextResponse.json({ error: (error as Error).message || "Internal error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { userService, walletService } from "@/lib/db/services";
import { authService } from "@/lib/auth/service";
import { emailService } from "@/lib/email/service";

export async function POST(_request: NextRequest) {
  try {
    const body = (await _request.json()) as {
      email?: string;
      username?: string;
      password?: string;
      name?: string;
    };

    // Validate input
    if (!body.email || !body.username || !body.password) {
      return NextResponse.json(
        { _error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Validate email format
    if (!authService.validateEmail(body.email)) {
      return NextResponse.json(
        { _error: "Invalid email format" },
        { status: 400 }
      );
    }

    // Validate password strength. Support both boolean quick-check and
    // detailed validator used elsewhere in the codebase.
    let passwordValidationResult: { isStrong: boolean; errors: string[] };
    if (
      typeof (authService as any).validatePasswordStrengthDetailed ===
      "function"
    ) {
      passwordValidationResult = (
        authService as any
      ).validatePasswordStrengthDetailed(body.password);
    } else {
      const ok = authService.validatePasswordStrength(body.password);
      passwordValidationResult = { isStrong: Boolean(ok), errors: [] };
    }
    if (!passwordValidationResult.isStrong) {
      return NextResponse.json(
        {
          _error: "password too weak",
          details: passwordValidationResult.errors,
        },
        { status: 400 }
      );
    }

    // Basic pre-check for duplicates to provide clear status codes in tests
    const existing = await userService.getByEmail(body.email);
    if (existing) {
      console.warn("REGISTER: existing found for", body.email, existing);
      return NextResponse.json(
        { _error: "Email already exists" },
        { status: 409 }
      );
    }

    // Create user (may still throw unique constraint in race conditions)
    const passwordHash = await authService.hashPassword(body.password);
    const user = await userService.create({
      email: body.email,
      username: body.username,
      name: body.name,
      passwordHash,
      role: "user",
    });

    // Ensure we can surface createdAt (some services/clients expect it).
    let createdAt: string | undefined = (user as any).createdAt;
    try {
      const fresh = await userService.getByEmail(user.email);
      if (fresh && (fresh as any).createdAt)
        createdAt = (fresh as any).createdAt;
    } catch (_e) {
      void _e; /* ignore */
    }

    // Create default wallet (USD)
    await walletService.create({
      userId: user.id,
      address: `wallet_${user.id}`,
      balance: '0',
      network: 'USD',
    });

    // Generate auth tokens
    const tokens = await authService.createAuthTokens(user.id, user.email);

    // Send welcome email
    try {
      // call with (template, to, data) to match existing test spies
      await emailService.sendTransactional("welcome", body.email, {
        name: body.name || body.username,
        email: body.email,
        confirmLink: `${process.env.NEXT_PUBLIC_API_URL}/api/auth/confirm?token=${tokens.accessToken}`,
        subject: "Welcome to QMOI Enhanced!",
      });
    } catch (emailError) {
      console.warn("Failed to send welcome email:", emailError);
      // Don't fail the _request if email fails
    }

    return NextResponse.json(
      {
        success: true,
        user: {
          id: (user as any).id,
          email: (user as any).email,
          username: (user as any).username,
          name: (user as any).name,
          createdAt: createdAt || new Date().toISOString(),
        },
        // Expose token fields at top-level for tests that expect them
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresIn: tokens.expiresIn,
      },
      { status: 201 }
    );
  } catch (_error) {
    // Handle unique constraint errors from Prisma mock or generated client
    try {
      const msg = error && (error as any).message;
      const code = error && (error as any).code;
      if (
        code === "P2002" ||
        (typeof msg === "string" && msg.toLowerCase().includes("unique"))
      ) {
        return NextResponse.json(
          { _error: "Email already exists" },
          { status: 409 }
        );
      }
    } catch (_e) {
      void _e; /* ignore */
    }
    (globalThis.console as any)?.error?.("Registration _error:", _error);
    return NextResponse.json(
      { _error: "Internal server error" },
      { status: 500 }
    );
  }
}

