          Authorization: `Bearer ${PESAPAL_CREDENTIALS.consumerKey}`,
        },
        body: `
        <PesapalDirectOrderInfo 
          xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" 
          xmlns:xsd="http://www.w3.org/2001/XMLSchema" 
          Amount="${transactionData.amount}" 
          Description="${transactionData.description}" 
          Type="MERCHANT" 
          Reference="${transactionData.reference}" 
          FirstName="QMOI" 
          LastName="Megavault" 
          Email="qmoialpha@gmail.com" 
          PhoneNumber="254700000000" 
          xmlns="http://www.pesapal.com" />
      `,
      }
    );

    const result = await response.text();
    return { success: true, transactionId: result, provider: "pesapal" };
  } catch (_error) {
    (console as any).error("Pesapal transaction failed:", _error);
    return { success: false, _error: "Pesapal transaction failed" };
  }
}

// Profit calculation functions
function calculateProfit(period: string, startDate: string, endDate: string) {
  const start = new Date(startDate);
  const end = new Date(endDate);

  // Filter transactions within period
  const periodTransactions = megavaultData.transactions.filter((t) => {
    const txDate = new Date(t.timestamp);
    return txDate >= start && txDate <= end;
  });

  const inflow = periodTransactions
    .filter((t) => t.type === "inflow")
    .reduce((sum, t) => sum + t.amount, 0);

  const outflow = periodTransactions
    .filter((t) => t.type === "outflow")
    .reduce((sum, t) => sum + t.amount, 0);

  const profit = inflow - outflow;

  return {
    period,
    startDate,
    endDate,
    inflow,
    outflow,
    profit,
    transactionCount: periodTransactions.length,
  };
}

// Dividend distribution functions
async function distributeDividends(distributionData: unknown) {
  try {
    const { percentage, recipients } = distributionData;
    const totalAmount = megavaultData.currentBalance * (percentage / 100);

    const distributions = recipients.map((recipient: unknown) => {
      const amount = totalAmount * (recipient.percentage / 100);
      return {
        recipientId: recipient.id,
        recipientType: recipient.type,
        amount,
        percentage: recipient.percentage,
        timestamp: Date.now(),
      };
    });

    // Update megavault balance
    megavaultData.currentBalance -= totalAmount;
    megavaultData.totalOutflow += totalAmount;
    megavaultData.totalDividends += totalAmount;

    // Log distributions
    distributions.forEach((dist: unknown) => {
      megavaultData.dividendHistory.push({
        id: `div_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        ...dist,
        status: "completed",
      });
    });

    // Log transaction
    megavaultData.transactions.push({
      id: `tx_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: "outflow",
      amount: totalAmount,
      description: `Dividend distribution (${percentage}%)`,
      timestamp: Date.now(),
      category: "dividend",
    });

    return { success: true, distributions, totalAmount };
  } catch (_error) {
    (console as any).error("Dividend distribution failed:", _error);
    return { success: false, _error: "Dividend distribution failed" };
  }
}

export async function GET(_request: NextRequest) {
  const { searchParams } = new URL(_request.url);
  const type = searchParams.get("type"); // 'balance', 'transactions', 'profit', 'dividends'
  const period = searchParams.get("period");
  const startDate = searchParams.get("startDate");
  const endDate = searchParams.get("endDate");

  try {
    switch (type) {
      case "balance":
        return NextResponse.json({
          success: true,
          data: {
            currentBalance: megavaultData.currentBalance,
            totalInflow: megavaultData.totalInflow,
            totalOutflow: megavaultData.totalOutflow,
            totalProfit: megavaultData.totalProfit,
            totalDividends: megavaultData.totalDividends,
          },
        });

      case "transactions":
        let transactions = megavaultData.transactions;
        if (startDate && endDate) {
          const start = new Date(startDate);
          const end = new Date(endDate);
          transactions = transactions.filter((t) => {
            const txDate = new Date(t.timestamp);
            return txDate >= start && txDate <= end;
          });
        }
        return NextResponse.json({ success: true, data: transactions });

      case "profit":
        if (period && startDate && endDate) {
          const profitData = calculateProfit(period, startDate, endDate);
          return NextResponse.json({ success: true, data: profitData });
        }
        return NextResponse.json({
          success: true,
          data: megavaultData.profitHistory,
        });

      case "dividends":
        return NextResponse.json({
          success: true,
          data: megavaultData.dividendHistory,
        });

      case "credentials":
        return NextResponse.json({
          success: true,
          data: {
            pesapal: {
              consumerKey: "***",
              environment: PESAPAL_CREDENTIALS.environment,
            },
          },
        });

      default:
        return NextResponse.json({
          success: true,
          data: megavaultData,
        });
    }
  } catch (_error) {
    return NextResponse.json(
      {
        success: false,
        _error: "Failed to fetch megavault data",
      },
      { status: 500 }
    );
  }
}

export async function POST(_request: NextRequest) {
  try {
    const body = await _request.json();
    const { action, ...data } = body;

    switch (action) {
      case "allocate_funds":
        const allocationData = FundAllocationSchema.parse(data);

        if (allocationData.amount > megavaultData.currentBalance) {
          return NextResponse.json(
            {
              success: false,
              _error: "Insufficient funds in Megavault",
            },
            { status: 400 }
          );
        }

        // Update balance
        megavaultData.currentBalance -= allocationData.amount;
        megavaultData.totalOutflow += allocationData.amount;

        // Log transaction
        const transaction = {
          id: `tx_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          type: "outflow",
          amount: allocationData.amount,
          description: allocationData.description,
          purpos_e: allocationData.purpos_e,
          targetAccount: allocationData.targetAccount,
          timestamp: Date.now(),
          category: "allocation",
        };

        megavaultData.transactions.push(transaction);

        return NextResponse.json({
          success: true,
          data: transaction,
          message: "Funds allocated successfully",
        });

      case "calculate_profit":
        const profitData = ProfitCalculationSchema.parse(data);
        const profitResult = calculateProfit(
          profitData.period,
          profitData.startDate,
          profitData.endDate
        );

        megavaultData.profitHistory.push({
          id: `profit_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          ...profitResult,
          calculatedAt: Date.now(),
        });

        return NextResponse.json({
          success: true,
          data: profitResult,
          message: "Profit calculated successfully",
        });

      case "distribute_dividends":
        const dividendData = DividendDistributionSchema.parse(data);
        const dividendResult = await distributeDividends(dividendData);

        if (!dividendResult.success) {
          return NextResponse.json(
            {
              success: false,
              _error: dividendResult.error,
            },
            { status: 500 }
          );
        }

        return NextResponse.json({
          success: true,
          data: dividendResult,
          message: "Dividends distributed successfully",
        });

      case "initialize_pesapal":
        const pesapalResult = await initializePesapalAccount();

        if (!pesapalResult.success) {
          return NextResponse.json(
            {
              success: false,
              _error: pesapalResult.error,
            },
            { status: 500 }
          );
        }

        return NextResponse.json({
          success: true,
          data: pesapalResult.account,
          message: "Pesapal account initialized successfully",
        });

      case "add_inflow":
        const { amount, description, source } = data;

        megavaultData.currentBalance += amount;
        megavaultData.totalInflow += amount;
        megavaultData.totalProfit += amount;

        const inflowTransaction = {
          id: `tx_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          type: "inflow",
          amount,
          description,
          source,
          timestamp: Date.now(),
          category: "revenue",
        };

        megavaultData.transactions.push(inflowTransaction);

        return NextResponse.json({
          success: true,
          data: inflowTransaction,
          message: "Inflow recorded successfully",
        });

      default:
        return NextResponse.json(
          {
            success: false,
            _error: "Invalid action specified",
          },
          { status: 400 }
        );
    }
  } catch (_error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
          _error: "Validation failed",
          details: error.errors,
        },
        { status: 400 }
      );
    }

    return NextResponse.json(
      {
        success: false,
        _error: "Failed to process megavault action",
      },
      { status: 500 }
    );
  }
}

export async function PUT(_request: NextRequest) {
  try {
    const body = await _request.json();
    const { id, ...updates } = body;

    // Find and update transaction
    const transactionIndex = megavaultData.transactions.findIndex(
      (t) => t.id === id
    );
    if (transactionIndex === -1) {
      return NextResponse.json(
        {
          success: false,
          _error: "Transaction not found",
        },
        { status: 404 }
      );
    }

    megavaultData.transactions[transactionIndex] = {
      ...megavaultData.transactions[transactionIndex],
      ...updates,
      updatedAt: Date.now(),
    };

    return NextResponse.json({
      success: true,
      data: megavaultData.transactions[transactionIndex],
      message: "Transaction updated successfully",
    });
  } catch (_error) {
    return NextResponse.json(
      {
        success: false,
        _error: "Failed to update transaction",
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db/prisma";
import authService from "@/lib/auth/service";

/**
 * GET /api/metrics
 * Get application metrics and statistics
 */
export async function GET(_request: NextRequest) {
  try {
    const token = _request.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return NextResponse.json(
        { _error: { message: "Missing authorization token", code: "NO_TOKEN" } },
        { status: 401 }
      );
    }

    let decoded;
    try {
      decoded = authService.verifyToken(token);
    } catch (_error) {
      return NextResponse.json(
        { _error: { message: "Invalid token", code: "INVALID_TOKEN" } },
        { status: 401 }
      );
    }

    if (!decoded || !decoded.userId) {
      return NextResponse.json(
        {
          _error: {
            message: "Invalid token (missing userId)",
            code: "INVALID_TOKEN",
          },
        },
        { status: 401 }
      );
    }

    // Check admin role
    const user = await db.userService.findById(String(decoded.userId));
    if (!user || user.role !== "admin") {
      return NextResponse.json(
        { _error: { message: "Insufficient permissions", code: "FORBIDDEN" } },
        { status: 403 }
      );
    }

    // Collect metrics
    const metrics = {
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      system: {
        totalUsers: await db.prisma.user.count(),
        activeUsers: await db.prisma.user.count({
          where: {
            lastLogin: {
              gte: new Date(Date.now() - 24 * 60 * 60 * 1000),
            },
          },
        }),
        totalWallets: await db.prisma.wallet.count(),
        totalTransactions: await db.prisma.transaction.count(),
        completedTransactions: await db.prisma.transaction.count({
          where: { status: "completed" },
        }),
        failedTransactions: await db.prisma.transaction.count({
          where: { status: "failed" },
        }),
      },
      database: {
        connectionStatus: "healthy",
        poolSize: "N/A",
      },
      performance: {
        avgResponseTime: "N/A",
        errorRate: "0%",
      },
    };

    // Calculate derived metrics
    const transactionSuccessRate =
      metrics.system.totalTransactions > 0
        ? (
            (metrics.system.completedTransactions /
              metrics.system.totalTransactions) *
            100
          ).toFixed(2)
        : 0;

    return NextResponse.json(
      {
        metrics: {
          ...metrics,
          derived: {
            transactionSuccessRate: `${transactionSuccessRate}%`,
            userGrowth24h: await calculateGrowth("user", 24),
            transactionVolume24h: await calculateTransactionVolume(24),
          },
        },
      },
      { status: 200 }
    );
  } catch (_error) {
    (globalThis.console as any)?.error?.("Metrics _error:", _error);
    return NextResponse.json(
      { _error: { message: "Internal server error", code: "SERVER_ERROR" } },
      { status: 500 }
    );
  }
}

async function calculateGrowth(type: string, hours: number): Promise<number> {
  const timeAgo = new Date(Date.now() - hours * 60 * 60 * 1000);

  if (type === "user") {
    const count = await db.prisma.user.count({
      where: {
        createdAt: { gte: timeAgo },
      },
    });
    return count;
  }

  return 0;
}

async function calculateTransactionVolume(hours: number): Promise<number> {
  const timeAgo = new Date(Date.now() - hours * 60 * 60 * 1000);

  const result = await db.prisma.transaction.aggregate({
    where: {
      createdAt: { gte: timeAgo },
      status: "completed",
    },
    _sum: { amount: true },
  });

  return result._sum.amount || 0;
}

import { NextRequest, NextResponse } from "next/server";
import * as jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET || "your-secret-key";

export type UserRole = "master" | "admin" | "user" | "sponsored" | "guest";

interface DecodedToken {
  id: string;
  username: string;
  role: UserRole;
  iat?: number;
  exp?: number;
}

/**
 * Extract JWT token from request headers
 */
export function getTokenFromRequest(request: NextRequest): string | null {
  const authHeader = request.headers.get("authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return null;
  }
  return authHeader.substring(7);
}

/**
 * Decode and verify JWT token
 */
export function verifyToken(token: string): DecodedToken | null {
  try {
    const decoded = jwt.verify(token, JWT_SECRET) as DecodedToken;
    return decoded;
  } catch (_error: unknown) {
    // Token verification failed - return null
    return null;
  }
}

/**
 * Get user role from request
 */
export function getRoleFromRequest(request: NextRequest): UserRole | null {
  const token = getTokenFromRequest(request);
  if (!token) {
    return null;
  }
  const decoded = verifyToken(token);
  return decoded?.role || null;
}

/**
 * Check if a role has permission for a specific action
 */
export function hasPermission(
  role: UserRole | null,
  requiredRole: UserRole | UserRole[]
): boolean {
  if (!role) {
    return false;
  }

  // Master has all permissions
  if (role === "master") {
    return true;
  }

  // Convert single role to array for comparison
  const requiredRoles = Array.isArray(requiredRole)
    ? requiredRole
    : [requiredRole];

  // Check if role matches any of the required roles
  return requiredRoles.includes(role);
}

/**
 * Middleware to protect API routes based on role
 */
export function withRoleProtection(
  handler: (
    request: NextRequest,
    context: { params: Record<string, string> }
  ) => Promise<Response>,
  requiredRoles: UserRole | UserRole[]
) {
  return async (
    request: NextRequest,
    context: { params: Record<string, string> }
  ) => {
    const userRole = getRoleFromRequest(request);

    if (!hasPermission(userRole, requiredRoles)) {
      return NextResponse.json(
        { error: "Forbidden: Insufficient permissions" },
        { status: 403 }
      );
    }

    return handler(request, context);
  };
}

/**
 * Role hierarchy (higher number = more permissions)
 */
export const roleHierarchy: Record<UserRole, number> = {
  master: 5,
  admin: 4,
  user: 2,
  sponsored: 1,
  guest: 0,
};

/**
 * Check if a role has at least the specified hierarchy level
 */
export function hasRoleLevel(role: UserRole, minLevel: number): boolean {
  return roleHierarchy[role] >= minLevel;
}

/**
 * Check if request user role is at or above a hierarchy level
 */
export function checkRoleLevel(
  request: NextRequest,
  minLevel: number
): boolean {
  const role = getRoleFromRequest(request);
  if (!role) {
    return false;
  }
  return hasRoleLevel(role, minLevel);
}

import { NextRequest, NextResponse } from "next/server";
import { paymentService } from "@/lib/payments/service";
import { transactionService, walletService } from "@/lib/db/services";
import { notificationService } from "@/lib/notifications/service";

export async function POST(_request: NextRequest) {
  try {
    const body = (await _request.json()) as {
      walletId?: string;
      amount?: number;
      currency?: string;
      description?: string;
      provider?: string;
      callbackUrl?: string;
      userEmail?: string;
      userPhone?: string;
    };

    // Validate input
    if (!body.walletId || !body.amount || body.amount <= 0) {
      return NextResponse.json(
        { _error: "Invalid payment parameters" },
        { status: 400 }
      );
    }

    const amount = Math.ceil(body.amount);
    const currency = body.currency || "KES";
    const provider = body.provider || "mpesa";

    // Create initial transaction record
    const transaction = await transactionService.create({
      walletId: body.walletId,
      type: "payment",
      amount,
      currency,
      status: "pending",
      reference: `TXN_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      details: {
        provider,
        description: body.description,
        initiatedAt: new Date().toISOString(),
      },
    });

    // Initiate payment with provider
    const paymentResponse = await paymentService.initiatePayment(
      {
        amount,
        currency,
        reference: transaction.reference,
        description: body.description || "Payment via QMOI Enhanced",
        userId: body.walletId,
        callbackUrl: body.callbackUrl,
        metadata: {
          transactionId: transaction.id,
          provider,
        },
      },
      provider
    );

    if (!paymentResponse.success) {
      // Update transaction to failed
      await transactionService.updateStatus(transaction.id, "failed");

      return NextResponse.json(
        { _error: paymentResponse.message },
        { status: 400 }
      );
    }

    // Update transaction with payment processor transaction ID
    await transactionService.updateStatus(transaction.id, "processing");

    // Send notification to user
    if (body.userEmail) {
      try {
        await notificationService.sendMultiChannel(
          {
            email: body.userEmail,
            phoneNumber: body.userPhone,
          },
          {
            title: "Payment Initiated",
            message: `Your payment of ${amount} ${currency} is being processed. Reference: ${transaction.reference}`,
            type: "info",
          },
          ["email"]
        );
      } catch (notifyError) {
        console.warn("Failed to send notification:", notifyError);
      }
    }

    return NextResponse.json({
      success: true,
      transaction: {
        id: transaction.id,
        reference: transaction.reference,
        amount,
        currency,
        status: "processing",
      },
      payment: {
        transactionId: paymentResponse.transactionId,
        redirectUrl: paymentResponse.redirectUrl,
      },
    });
  } catch (_error) {
    (globalThis.console as any)?.error?.("Payment initiation _error:", _error);
    return NextResponse.json(
      { _error: "Payment initiation failed" },
      { status: 500 }
    );
  }
}

