    const discussions = await prisma.discussion.findMany({
      where: {
        OR: [
          { title: { contains: query, mode: "insensitive" } },
          { content: { contains: query, mode: "insensitive" } },
          { tags: { hasSome: [query] } },
        ],
      },
      include: {
        author: {
          select: {
