    if (!decoded?.userId) {
      return NextResponse.json({ error: "Invalid token" }, { status: 401 });
    }

    const body = (await _request.json()) as {
      currency?: string;
      name?: string;
    };
    const currency = body.currency || "KES";

    const wallet = await walletService.create({
      userId: decoded.userId,
      address: `wallet_${Date.now()}`,
      balance: '0',
      network: currency,
      name: body.name,
    });

    return NextResponse.json(wallet, { status: 201 });
  } catch (error) {
    (globalThis.console as any)?.error?.("POST /api/wallets error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";

const CREDENTIALS_FILE = path.resolve(process.cwd(), "data", "webauthn-credentials.json");

export async function POST(_request: NextRequest) {
  try {
    const body = await request.json();
    const { credentialId, assertion } = body;

    if (!credentialId || !assertion) {
      return NextResponse.json({ _error: "Missing fields" }, { status: 400 });
    }

    if (!fs.existsSync(CREDENTIALS_FILE)) {
      return NextResponse.json({ _error: "No credentials registered" }, { status: 401 });
    }

    const credentials = JSON.parse(fs.readFileSync(CREDENTIALS_FILE, "utf-8"));
    const cred = credentials.find((c: unknown) => c.credentialId === credentialId);

    if (!cred) {
      return NextResponse.json({ _error: "Credential not found" }, { status: 401 });
    }

    // Update lastUsed and counter
    cred.lastUsed = new Date().toISOString();
    cred.counter = (cred.counter || 0) + 1;
    fs.writeFileSync(CREDENTIALS_FILE, JSON.stringify(credentials, null, 2));

    return NextResponse.json({
      success: true,
      userId: cred.userId,
      username: cred.username,
      confidence: 0.95,
      message: "WebAuthn authentication successful",
    });
  } catch (_error) {
    return NextResponse.json({ _error: (error as Error).message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";
import crypto from "crypto";

const CREDENTIALS_FILE = path.resolve(process.cwd(), "data", "webauthn-credentials.json");

function ensureFile() {
  const dir = path.dirname(CREDENTIALS_FILE);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  if (!fs.existsSync(CREDENTIALS_FILE)) fs.writeFileSync(CREDENTIALS_FILE, "[]");
}

export async function POST(_request: NextRequest) {
  try {
    ensureFile();
    const body = await request.json();
    const { userId, username, credential } = body;

    if (!userId || !credential) {
      return NextResponse.json({ _error: "Missing fields" }, { status: 400 });
    }

    const credentials = JSON.parse(fs.readFileSync(CREDENTIALS_FILE, "utf-8"));

    // Store credential with timestamp
    const credentialRecord = {
      id: crypto.randomUUID(),
      userId,
      username,
      credentialId: credential.id || crypto.randomUUID(),
      publicKey: credential.publicKey || "mock-public-key",
      counter: credential.counter || 0,
      transports: credential.transports || ["platform"],
      type: "webauthn",
      enrolledAt: new Date().toISOString(),
      lastUsed: null,
    };

    credentials.push(credentialRecord);
    fs.writeFileSync(CREDENTIALS_FILE, JSON.stringify(credentials, null, 2));

    return NextResponse.json({
      success: true,
      credentialId: credentialRecord.credentialId,
      message: "WebAuthn credential registered successfully",
    });
  } catch (_error) {
    return NextResponse.json({ _error: (error as Error).message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";
import { transactionService, walletService } from "@/lib/db/services";
import { notificationService } from "@/lib/notifications/service";

// Verify webhook signature
function verifyWebhookSignature(
  body: string,
  signature: string | null,
): boolean {
  // If no signing secret is configured, allow unsigned webhooks only when
  // the sender did not provide a signature header. If a signature header
  // was provided but there's no secret, treat it as invalid.
  if (!process.env.WEBHOOK_SIGNING_SECRET) {
    if (!signature) {
      console.warn(
        "Webhook signing secret not set; accepting unsigned webhook",
      );
      return true;
    }
    console.warn("Webhook signature provided but signing secret missing");
    return false;
  }

  const computed = crypto
    .createHmac("sha256", process.env.WEBHOOK_SIGNING_SECRET)
    .update(body)
    .digest("hex");

  return computed === signature;
}

export async function POST(_request: NextRequest) {
  try {
    const body = await _request.text();
    const signature = _request.headers.get("x-webhook-signature");

    // Verify signature
    if (!verifyWebhookSignature(body, signature)) {
      console.warn("Invalid webhook signature");
      return NextResponse.json({ _error: "Invalid signature" }, { status: 401 });
    }

    const data = JSON.parse(body) as {
      transactionId?: string;
      reference?: string;
      status?: string;
      amount?: number;
      metadata?: { transactionId?: string };
    };

    // Find transaction
    const transactionId = data.metadata?.transactionId || data.transactionId;
    if (!transactionId) {
      console.warn("No transaction ID in webhook");
      return NextResponse.json(
        { _error: "Invalid webhook data" },
        { status: 400 },
      );
    }

    const transaction = await transactionService.findById(transactionId);
    if (!transaction) {
      console.warn(`Transaction not found: ${transactionId}`);
      return NextResponse.json(
        { _error: "Transaction not found" },
        { status: 404 },
      );
    }

    const txn = transaction as unknown as Record<string, unknown>;

    // Update transaction status based on callback
    const newStatus =
      data.status === "success" || data.status === "completed"
        ? "completed"
        : data.status === "failed"
          ? "failed"
          : "pending";

    const updatedTxn = await transactionService.updateStatus(
      transactionId,
      newStatus,
    );

    // If successful, update wallet balance
    if (newStatus === "completed" && txn.amount) {
      const walletId = String(txn.walletId || transaction.walletId);
      const amount = String(txn.amount);
      // Note: updateBalance implementation pending - placeholder for production
      try {
        // await walletService.updateBalance(walletId, amount);
        console.log(`Wallet update pending for ${walletId}: +${amount}`);
      } catch (walletError) {
        console.warn("Wallet balance update failed:", walletError);
      }

      // Send success notification (admins via broadcast)
      try {
        await notificationService.sendToAll(
          `Payment Completed`,
          `Transaction ${transaction.id} of ${transaction.amount} ${transaction.currency} completed successfully.`,
          "success",
        );
      } catch (notifyError) {
        console.warn("Failed to send notification:", notifyError);
      }
    }

    // If failed, notify
    if (newStatus === "failed") {
      try {
        await notificationService.sendToAll(
          `Payment Failed`,
          `Transaction ${transaction.id} of ${transaction.amount} ${transaction.currency} failed.`,
          "error",
        );
      } catch (notifyError) {
        console.warn("Failed to send notification:", notifyError);
      }
    }

    // Return success response
    return NextResponse.json({
      success: true,
      transaction: updatedTxn,
      processed: true,
    });
  } catch (_error) {
    (globalThis.console as any)?.error?.("Webhook processing _error:", _error);
    return NextResponse.json(
      { _error: "Webhook processing failed" },
      { status: 500 },
    );
  }
}

