export function RegisterForm() {
  const router = useRouter();
  const [formData, setFormData] = useState({
    email: "",
    username: "",
    password: "",
    confirmPassword: "",
  });
  const [_error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (_e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = _e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (_e: React.FormEvent<HTMLFormElement>) => {
    _e.preventDefault();
    setError("");
    setLoading(true);

    try {
      // Validate form
      if (!formData.email || !formData.username || !formData.password) {
        setError("All fields are required");
        setLoading(false);
        return;
      }

      if (formData.password !== formData.confirmPassword) {
        setError("Passwords do not match");
        setLoading(false);
        return;
      }

      // Call registration API
      const _response = await fetch("/api/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: formData.email,
          username: formData.username,
          password: formData.password,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        setError(data.error || "Registration failed");
        setLoading(false);
        return;
      }

      const { accessToken, user } = await response.json();

      // Store token
      localStorage.setItem("accessToken", accessToken);
      localStorage.setItem("user", JSON.stringify(user));

      // Redirect to dashboard
      router.push("/dashboard");
    } catch (_err) {
      setError(_err instanceof Error ? _err.message : "An error occurred");
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 max-w-md mx-auto">
      <h1 className="text-2xl font-bold mb-6">Create Account</h1>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
          {error}
        </div>
      )}

      <div>
        <label htmlFor="email" className="block text-sm font-medium mb-1">
          Email
        </label>
        <input
          type="email"
          id="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="you@example.com"
          required
        />
      </div>

      <div>
        <label htmlFor="username" className="block text-sm font-medium mb-1">
          Username
        </label>
        <input
          type="text"
          id="username"
          name="username"
          value={formData.username}
          onChange={handleChange}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="johndoe"
          required
        />
      </div>

      <div>
        <label htmlFor="password" className="block text-sm font-medium mb-1">
          Password
        </label>
        <input
          type="password"
          id="password"
          name="password"
          value={formData.password}
          onChange={handleChange}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="••••••••"
          required
        />
        <p className="text-xs text-gray-500 mt-1">
          At least 8 characters with uppercase, numbers, and special characters
        </p>
      </div>

      <div>
        <label
          htmlFor="confirmPassword"
          className="block text-sm font-medium mb-1"
        >
          Confirm Password
        </label>
        <input
          type="password"
          id="confirmPassword"
          name="confirmPassword"
          value={formData.confirmPassword}
          onChange={handleChange}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="••••••••"
          required
        />
      </div>

      <button
        type="submit"
        disabled={loading}
        className="w-full bg-blue-600 text-white py-2 rounded-lg font-medium hover:bg-blue-700 disabled:bg-gray-400 transition"
      >
        {loading ? "Creating account..." : "Create Account"}
      </button>

      <p className="text-center text-sm text-gray-600">
        Already have an account?{" "}
        <a href="/login" className="text-blue-600 hover:underline">
          Sign in
        </a>
      </p>
    </form>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

interface UserProfile {
  id: string;
  email: string;
  username: string;
  firstName?: string;
  lastName?: string;
  phoneNumber?: string;
  dateOfBirth?: string;
  bio?: string;
  createdAt: string;
}

export function UserProfile() {
  const router = useRouter();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [_error, setError] = useState("");
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    phoneNumber: "",
    dateOfBirth: "",
    bio: "",
  });

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("accessToken");
      if (!token) {
        router.push("/login");
        return;
      }

      const _response = await fetch("/api/users/profile", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        if (response.status === 401) {
          router.push("/login");
          return;
        }
        setError("Failed to load profile");
        return;
      }

      const data = await response.json();
      setProfile(data);
      setFormData({
        firstName: data.firstName || "",
        lastName: data.lastName || "",
        phoneNumber: data.phoneNumber || "",
        dateOfBirth: data.dateOfBirth || "",
        bio: data.bio || "",
      });
    } catch (_err) {
      setError(_err instanceof Error ? _err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (
    _e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = _e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSave = async (_e: React.FormEvent<HTMLFormElement>) => {
    _e.preventDefault();
    setSaving(true);

    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        router.push("/login");
        return;
      }

      const _response = await fetch("/api/users/profile", {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        setError("Failed to update profile");
        return;
      }

      const updatedProfile = await response.json();
      setProfile(updatedProfile);
      setEditing(false);
    } catch (_err) {
      setError(_err instanceof Error ? _err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="text-center py-8">Loading profile...</div>;
  }

  if (!profile) {
    return <div className="text-center py-8">Profile not found</div>;
  }

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-lg shadow-lg">
        {/* Header */}
        <div className="border-b p-6">
          <h1 className="text-3xl font-bold">{profile.username}</h1>
          <p className="text-gray-600">{profile.email}</p>
        </div>

        {error && (
          <div className="bg-red-50 border-b border-red-200 text-red-700 px-6 py-3">
            {error}
          </div>
        )}

        {/* Profile Content */}
        <div className="p-6">
          {!editing ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium text-gray-600">
                    First Name
                  </label>
                  <p className="mt-1 text-lg">{profile.firstName || "—"}</p>
                </div>
                <div>
                  <label className="text-sm font-medium text-gray-600">
                    Last Name
                  </label>
                  <p className="mt-1 text-lg">{profile.lastName || "—"}</p>
                </div>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Phone Number
                </label>
                <p className="mt-1 text-lg">{profile.phoneNumber || "—"}</p>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Date of Birth
                </label>
                <p className="mt-1 text-lg">
                  {profile.dateOfBirth
                    ? new Date(profile.dateOfBirth).toLocaleDateString()
                    : "—"}
                </p>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">Bio</label>
                <p className="mt-1 text-lg">{profile.bio || "—"}</p>
              </div>

              <div className="pt-4">
                <label className="text-sm font-medium text-gray-600">
                  Member Since
                </label>
                <p className="mt-1 text-lg">
                  {new Date(profile.createdAt).toLocaleDateString()}
                </p>
              </div>

              <button
                onClick={() => setEditing(true)}
                className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition"
              >
                Edit Profile
              </button>
            </div>
          ) : (
            <form onSubmit={handleSave} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label
                    htmlFor="firstName"
                    className="block text-sm font-medium mb-1"
                  >
                    First Name
                  </label>
                  <input
                    type="text"
                    id="firstName"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label
                    htmlFor="lastName"
                    className="block text-sm font-medium mb-1"
                  >
                    Last Name
                  </label>
                  <input
                    type="text"
                    id="lastName"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              <div>
                <label
                  htmlFor="phoneNumber"
                  className="block text-sm font-medium mb-1"
                >
                  Phone Number
                </label>
                <input
                  type="tel"
                  id="phoneNumber"
                  name="phoneNumber"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label
                  htmlFor="dateOfBirth"
                  className="block text-sm font-medium mb-1"
                >
                  Date of Birth
                </label>
                <input
                  type="date"
                  id="dateOfBirth"
                  name="dateOfBirth"
                  value={formData.dateOfBirth}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label htmlFor="bio" className="block text-sm font-medium mb-1">
                  Bio
                </label>
                <textarea
                  id="bio"
                  name="bio"
                  value={formData.bio}
                  onChange={handleChange}
                  rows={4}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="flex gap-2 pt-4">
                <button
                  type="submit"
                  disabled={saving}
                  className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 disabled:bg-gray-400 transition"
                >
                  {saving ? "Saving..." : "Save Changes"}
                </button>
                <button
                  type="button"
                  onClick={() => setEditing(false)}
                  className="bg-gray-400 text-white px-6 py-2 rounded-lg hover:bg-gray-500 transition"
                >
                  Cancel
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

interface Wallet {
  id: string;
  currency: string;
  balance: number;
  publicKey?: string;
}

export function WalletList() {
  const router = useRouter();
  const [wallets, setWallets] = useState<Wallet[]>([]);
  const [loading, setLoading] = useState(true);
  const [_error, setError] = useState("");
  const [creatingWallet, setCreatingWallet] = useState(false);
  const [newCurrency, setNewCurrency] = useState("KES");

  useEffect(() => {
    fetchWallets();
  }, []);

  const fetchWallets = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("accessToken");
      if (!token) {
        router.push("/login");
        return;
      }

      const _response = await fetch("/api/wallets", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        if (response.status === 401) {
          router.push("/login");
          return;
        }
        setError("Failed to load wallets");
        return;
      }

      const data = await response.json();
      setWallets(data.wallets || []);
    } catch (_err) {
      setError(_err instanceof Error ? _err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateWallet = async (_e: React.FormEvent<HTMLFormElement>) => {
    _e.preventDefault();
    setCreatingWallet(true);

    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        router.push("/login");
        return;
      }

      const _response = await fetch("/api/wallets", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ currency: newCurrency }),
      });

      if (!response.ok) {
        setError("Failed to create wallet");
        return;
      }

      const newWallet = await response.json();
      setWallets([...wallets, newWallet]);
      setNewCurrency("KES");
    } catch (_err) {
      setError(_err instanceof Error ? _err.message : "An error occurred");
    } finally {
      setCreatingWallet(false);
    }
  };

  if (loading) {
    return <div className="text-center py-8">Loading wallets...</div>;
  }

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold">My Wallets</h2>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
          {error}
        </div>
      )}

      {/* Wallet List */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {wallets.map((wallet) => (
          <div
            key={wallet.id}
            className="border rounded-lg p-6 hover:shadow-lg transition"
          >
            <h3 className="text-lg font-semibold mb-2">
              {wallet.currency} Wallet
            </h3>
            <p className="text-3xl font-bold text-blue-600 mb-2">
              {wallet.balance.toFixed(2)} {wallet.currency}
            </p>
            <p className="text-sm text-gray-500 mb-4">
              ID: {wallet.id.slice(0, 8)}...
            </p>
            <button
              onClick={() => router.push(`/wallets/${wallet.id}`)}
              className="bg-blue-600 text-white px-4 py-2 rounded text-sm hover:bg-blue-700 transition"
            >
              View Details
            </button>
          </div>
        ))}
      </div>

      {wallets.length === 0 && (
        <p className="text-gray-600 text-center py-8">No wallets yet</p>
      )}

      {/* Create Wallet Form */}
      <form
        onSubmit={handleCreateWallet}
        className="border rounded-lg p-6 bg-gray-50"
      >
        <h3 className="text-lg font-semibold mb-4">Create New Wallet</h3>
        <div className="flex gap-2">
          <select
            value={newCurrency}
            onChange={(_e) => setNewCurrency(_e.target.value)}
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="KES">KES (Kenyan Shilling)</option>
            <option value="USD">USD (US Dollar)</option>
            <option value="EUR">EUR (Euro)</option>
            <option value="GBP">GBP (British Pound)</option>
            <option value="UGX">UGX (Uganda Shilling)</option>
            <option value="TZS">TZS (Tanzanian Shilling)</option>
          </select>
          <button
            type="submit"
            disabled={creatingWallet}
            className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 disabled:bg-gray-400 transition"
          >
            {creatingWallet ? "Creating..." : "Create"}
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import QMOIDashboard from "../components/QMOIDashboard";
import BiometricAuth from "../components/BiometricAuth";
import { MasterProvider, useMaster } from "../components/MasterContext";
import { NotificationPanel } from "../components/NotificationPanel";

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  avatar?: string;
}

function MainPage() {
  const { isMaster, setRole, setCurrentUser: setMasterUser, updateQMOIMemory } = useMaster();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>({
    id: "1",
    name: "Victor Kwemoi",
    email: "victor@qmoi.com",
    role: "Master Administrator",
    avatar: undefined,
  });
  const [loginMode, setLoginMode] = useState<"form" | "quick">("quick");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  // Check authentication status
  useEffect(() => {
    // In a real implementation, this would check for valid session/token
    const checkAuth = () => {
      const storedAuth = localStorage.getItem("qmoi_authenticated");
      if (storedAuth === "true") {
        setIsAuthenticated(true);
        // Load user data from localStorage or API
        const storedUser = localStorage.getItem("qmoi_user");
        if (storedUser) {
          const userData = JSON.parse(storedUser);
          setCurrentUser(userData);
          // Update QMOI awareness with user context
          setMasterUser(userData);
          updateQMOIMemory({
            conversations: (Math.random() * 100) | 0,
            preferences: {
              language: "en",
              timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
            },
            contextHistory: [`User ${userData.name} authenticated`],
          });
        }
      }
    };

    checkAuth();
  }, [setMasterUser, updateQMOIMemory]);

  const handleLogin = (userData: unknown) => {
    const u = (userData as Partial<User>) || {};
    const roleString = String(u.role || "User");
    const roleMap: Record<string, "master" | "admin" | "user" | "sponsored" | "guest"> = {
      "Master Administrator": "master",
      Administrator: "admin",
      "Sister": "admin",
      User: "user",
      "Sponsored User": "sponsored",
      Master: "master",
      Admin: "admin",
      Sponsored: "sponsored",
    };
    const mappedRole = roleMap[roleString] || "user";

    const user: User = {
      id: String(u.id || "1"),
      name: String(u.name || "Unknown"),
      email: String(u.email || "unknown@qmoi"),
      role: roleString,
      avatar: u.avatar,
    };

    setCurrentUser(user);
    setIsAuthenticated(true);

    // Update QMOI awareness with user context - cast to UserProfile type
    setMasterUser({
      id: user.id,
      name: user.name,
      email: user.email,
      role: mappedRole,
      avatar: user.avatar,
    });
    setRole(mappedRole);

    // Update QMOI memory with user interaction
    updateQMOIMemory({
      conversations: (Math.random() * 50) | 0,
      preferences: {
        language: "en",
        avatar: user.avatar,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      },
      contextHistory: [`User ${user.name} (${user.role}) logged in`],
    });

    localStorage.setItem("qmoi_authenticated", "true");
    localStorage.setItem("qmoi_user", JSON.stringify(user));
  };

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setIsLoading(true);

    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: email, password }),
      });

      if (!response.ok) {
        const data = await response.json();
        setError(data.error || "Login failed");
        setIsLoading(false);
        return;
      }

      const data = await response.json();
      handleLogin({
        id: data.user.id,
        name: data.user.username,
        email: email,
        role: data.user.role || "User",
      });
    } catch (err: unknown) {
      setError("Network error. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser({
      id: "1",
      name: "Victor Kwemoi",
      email: "victor@qmoi.com",
      role: "Master Administrator",
      avatar: undefined,
    });
    localStorage.removeItem("qmoi_authenticated");
    localStorage.removeItem("qmoi_user");
  };

  // If not authenticated, show login/auth interface
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full">
          <div className="bg-white rounded-lg shadow-lg p-8">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-gradient-to-br from-blue-600 to-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-white font-bold text-xl">QM</span>
              </div>
              <h1 className="text-2xl font-bold text-gray-900">
                QMOI Enhanced
              </h1>
              <p className="text-gray-600 mt-2">Advanced AI System Access</p>
              <p className="text-xs text-blue-600 font-semibold mt-3">
                🔐 Master Administrator (Victor Kwemoi) - System Admin
              </p>
            </div>

            {/* Mode Toggle */}
            <div className="flex gap-2 mb-6 bg-gray-100 p-1 rounded-lg">
              <button
                onClick={() => setLoginMode("form")}
                className={`flex-1 py-2 rounded-md font-medium transition-colors ${
                  loginMode === "form"
                    ? "bg-white text-blue-600 shadow-sm"
                    : "text-gray-600"
                }`}
              >
                Email Login
              </button>
              <button
                onClick={() => setLoginMode("quick")}
                className={`flex-1 py-2 rounded-md font-medium transition-colors ${
                  loginMode === "quick"
                    ? "bg-white text-blue-600 shadow-sm"
                    : "text-gray-600"
                }`}
              >
                Quick Access
              </button>
            </div>

            {/* Email/Password Login Form */}
            {loginMode === "form" && (
              <form onSubmit={handleEmailLogin} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Email or Username
                  </label>
                  <input
                    type="text"
                    value={email}
