import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Chip,
  IconButton,
  Tooltip,
  CircularProgress,
  Alert,
} from "@mui/material";
import { AccountBalance, Refresh, Info } from "@mui/icons-material";
import { useAuth } from "../hooks/useAuth";
import { AssetManagerImpl, Asset } from "../config/assets";

interface AssetOverviewProps {
  className?: string;
}

export const AssetOverview: React.FC<AssetOverviewProps> = ({ className }) => {
  const { user } = useAuth();
  const [assets, setAssets] = useState<Asset[]>([]);
  const [opportunities, setOpportunities] = useState<
    Array<{
      type: string;
      opportunity: string;
      potentialProfit: number;
      risk: "low" | "medium" | "high";
    }>
  >([]);
  const [isLoading, setIsLoading] = useState(true);
  const [_error, setError] = useState<string | null>(null);
  const [totalBalance, setTotalBalance] = useState(0);

  const fetchData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const assetManager = AssetManagerImpl.getInstance();
      const [assetsData, opportunitiesData, total] = await Promise.all([
        assetManager.getAssets(),
        assetManager.getProfitOpportunities(),
        assetManager.getTotalBalance(),
      ]);

      setAssets(assetsData);
      setOpportunities(opportunitiesData);
      setTotalBalance(total);
    } catch (_err) {
      void _err;
      setError(
        _err instanceof Error ? _err.message : "Failed to fetch asset data"
      );
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000); // Update every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(amount);
  };

  const formatBalance = (balance: number, currency: string) => {
    if (currency === "BTC") {
      return balance.toFixed(8);
    }
    return balance.toFixed(2);
  };

  const getAssetTypeColor = (type: Asset["type"]) => {
    switch (type) {
      case "spot":
        return "primary";
      case "futures":
        return "secondary";
      case "otc":
        return "success";
      default:
        return "default";
    }
  };

  const getRiskColor = (risk: string) => {
    switch (risk) {
      case "low":
        return "success";
      case "medium":
        return "warning";
      case "high":
        return "error";
      default:
        return "default";
    }
  };

  if (!user || !["master", "sister"].includes(user.role)) {
    return null;
  }

  return (
    <Card className={className}>
      <CardContent>
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={2}
        >
          <Typography variant="h6" component="h2">
            Asset Overview
          </Typography>
          <Box display="flex" alignItems="center" gap={1}>
            <Typography variant="h6" color="primary">
              {formatCurrency(totalBalance)}
            </Typography>
            <Tooltip title="Refresh Assets">
              <IconButton size="small" onClick={fetchData} disabled={isLoading}>
                <Refresh />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {isLoading ? (
          <Box display="flex" justifyContent="center" p={2}>
            <CircularProgress size={24} />
          </Box>
        ) : (
          <>
            <Grid container spacing={2} mb={3}>
              {assets.map((asset) => (
                <Grid size={4} key={`${asset.type}_${asset.currency}`}>
                  <Card variant="outlined">
                    <CardContent>
                      <Box display="flex" alignItems="center" gap={1} mb={1}>
                        <AccountBalance fontSize="small" />
                        <Typography variant="subtitle2">
                          {asset.type.toUpperCase()} - {asset.currency}
                        </Typography>
                      </Box>
                      <Typography variant="h6">
                        {formatBalance(asset.balance, asset.currency)}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        ≈ {formatCurrency(asset.usdValue)}
                      </Typography>
                      <Chip
                        size="small"
                        label={asset.type}
                        color={getAssetTypeColor(asset.type)}
                        sx={{ mt: 1 }}
                      />
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>

            <Typography variant="h6" gutterBottom>
              Profit Opportunities
            </Typography>
            <Grid container spacing={2}>
              {opportunities.map((opp, index) => (
                <Grid size={6} key={index}>
                  <Card variant="outlined">
                    <CardContent>
                      <Box
                        display="flex"
                        justifyContent="space-between"
                        alignItems="center"
                      >
                        <Box>
                          <Typography variant="subtitle2">
                            {opp.opportunity}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {opp.type.toUpperCase()}
                          </Typography>
                        </Box>
                        <Box textAlign="right">
                          <Typography variant="h6" color="success.main">
                            +{formatCurrency(opp.potentialProfit)}
                          </Typography>
                          <Chip
                            size="small"
                            label={`Risk: ${opp.risk}`}
                            color={getRiskColor(opp.risk)}
                          />
                        </Box>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </>
        )}

        <Box mt={2}>
          <Alert severity="info" icon={<Info />}>
            Asset balances are automatically updated every 30 seconds. Click the
            refresh button to update manually.
          </Alert>
        </Box>
      </CardContent>
    </Card>
  );
};

"use client";
import React, { useState, useRef, useEffect } from "react";
import { playSSML, supportsSpeechSynthesis } from "../services/tts";
import "./Chatbot.css";

interface ChatMessage {
  id: string;
  text: string;
  sender: "user" | "bot";
  timestamp: Date;
}

export function Chatbot() {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: "1",
      text: "Hello! I'm the QMOI AI Assistant. How can I help you today?",
      sender: "bot",
      timestamp: new Date(),
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async () => {
    if (!input.trim()) return;

    // Add user message
    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      text: input,
      sender: "user",
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    // Call model endpoint and _request speak (SSML) when supported
    try {
      const wantSpeak = supportsSpeechSynthesis();
      const { postModel } = await import("../services/qmoiApi");
      const data = await postModel({
        user: "local",
        message: input,
        speak: wantSpeak,
      });
      const dataAny = data as any;
      let replyText = "";
      if (dataAny && dataAny.reply) replyText = dataAny.reply;
      else if (
        dataAny &&
        dataAny.choices &&
        Array.isArray(dataAny.choices) &&
        dataAny.choices[0]
      ) {
        replyText =
          dataAny.choices[0].message?.content || dataAny.choices[0]?.text || "";
      } else {
        replyText = "Sorry, I could not get a reply.";
      }
      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: replyText,
        sender: "bot",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botMessage]);

      // Best-effort: report updated conversation length to QMOI memory API
      try {
        fetch("/api/qmoi/memory", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessions: {
              local: {
                conversations: (messages.length || 0) + 2,
                last_prompt: input,
              },
            },
          }),
        }).catch(() => {});
      } catch (_e) {}

      // Play SSML if provided
      if (dataAny && dataAny.ssml) {
        // best-effort playback
        playSSML(dataAny.ssml);
      }
    } catch (_err) {
      void _err;
      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: "Error: could not reach QMOI backend",
        sender: "bot",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botMessage]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="chatbot-container">
      <div className="chatbot-header">
        <h2>QMOI AI Chat</h2>
        <span className="status-badge">Ready</span>
      </div>
      <div className="chatbot-messages">
        {messages.map((msg) => (
          <div key={msg.id} className={`message message-${msg.sender}`}>
            <div className="message-content">{msg.text}</div>
            <div className="message-time">
              {msg.timestamp.toLocaleTimeString()}
            </div>
          </div>
        ))}
        {loading && (
          <div className="message message-bot loading">
            <div className="typing-indicator">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>
      <div className="chatbot-input">
        <input
          type="text"
          placeholder="Type your message..."
          value={input}
          onChange={(_e) => setInput(_e.target.value)}
          onKeyPress={(_e) => _e.key === "Enter" && handleSendMessage()}
          disabled={loading}
        />
        <button onClick={handleSendMessage} disabled={loading || !input.trim()}>
          Send
        </button>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useAuth } from "../hooks/useAuth";
import { Button, CircularProgress, Snackbar, Alert } from "@mui/material";
import { Download as DownloadIcon } from "@mui/icons-material";

interface DownloadQCityProps {
  className?: string;
}

export const DownloadQCity: React.FC<DownloadQCityProps> = ({ className }) => {
  const { user, hasAccess } = useAuth();
  const [downloading, setDownloading] = useState(false);
  const [_error, setError] = useState<string | null>(null);

  const handleDownload = async () => {
    try {
      setDownloading(true);
      setError(null);

      // Check if user has access
      const canDownload = await hasAccess("download_qcity");
      if (!canDownload) {
        throw new Error("You do not have permission to download Q-city");
      }

      // Get download URL
      const _response = await fetch("/api/qcity/download-url");
      if (!response.ok) {
        throw new Error("Failed to get download URL");
      }

      const { url } = await response.json();

      // Start download
      const downloadResponse = await fetch(url);
      if (!downloadResponse.ok) {
        throw new Error("Failed to download Q-city");
      }

      // Create blob and download
      const blob = await downloadResponse.blob();
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = downloadUrl;
      link.download = "q-city-setup.exe";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);
    } catch (_err) {
      void _err;
      setError(_err instanceof Error ? _err.message : "An error occurred");
    } finally {
      setDownloading(false);
    }
  };

  // Only show to master users
  if (!user || user.role !== "master") {
    return null;
  }

  return (
    <div className={className}>
      <Button
        variant="contained"
        color="primary"
        startIcon={
          downloading ? (
            <CircularProgress size={20} color="inherit" />
          ) : (
            <DownloadIcon />
          )
        }
        onClick={handleDownload}
        disabled={downloading}
      >
        {downloading ? "Downloading..." : "Download Q-city"}
      </Button>

      <Snackbar
        open={!!error}
        autoHideDuration={6000}
        onClose={() => setError(null)}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert onClose={() => setError(null)} severity="error">
          {error}
        </Alert>
      </Snackbar>
    </div>
  );
};

