  Alert,
} from "@mui/material";
import { TrendingUp, TrendingDown, Refresh, Info } from "@mui/icons-material";
import { useAuth } from "../hooks/useAuth";
import { TradingManager } from "../config/trading";

interface Trade {
  id: string;
  timestamp: Date;
  pair: string;
  type: "buy" | "sell";
  amount: number;
  price: number;
  total: number;
  profit?: number;
  status: "completed" | "failed" | "pending";
  userId: string;
  userRole: string;
}

interface TradingHistoryProps {
  className?: string;
}

export const TradingHistory: React.FC<TradingHistoryProps> = ({
  className,
}) => {
  const { user } = useAuth();
  const [trades, setTrades] = useState<Trade[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [_error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState({
    totalTrades: 0,
    successfulTrades: 0,
    totalProfit: 0,
    winRate: 0,
  });

  const fetchTrades = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const tradingManager = TradingManager.getInstance();
      const rawHistory = (await tradingManager.getTradingHistory()) as any[];
      const history = rawHistory.map((trade: unknown) => ({
        ...trade,
        timestamp: new Date(trade?.timestamp),
      }));
      setTrades(history as Trade[]);

      // Calculate statistics
      const successfulTrades = history.filter(
        (t: Trade) => t.status === "completed"
      );
      const totalProfit = successfulTrades.reduce(
        (sum: number, trade: Trade) => sum + (trade.profit || 0),
        0
      );
      const winRate = (successfulTrades.length / history.length) * 100;

      setStats({
        totalTrades: history.length,
        successfulTrades: successfulTrades.length,
        totalProfit,
        winRate,
      });
    } catch (_err) {
      void _err;
      setError(
        _err instanceof Error ? _err.message : "Failed to fetch trading history"
      );
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchTrades();
    const interval = setInterval(fetchTrades, 60000); // Update every minute
    return () => clearInterval(interval);
  }, []);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(amount);
  };

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat("en-US", {
      dateStyle: "short",
      timeStyle: "medium",
    }).format(date);
  };

  if (!user || !["master", "sister"].includes(user.role)) {
    return null;
  }

  return (
    <Card className={className}>
      <CardContent>
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={2}
        >
          <Typography variant="h6" component="h2">
            Trading History
          </Typography>
          <Box display="flex" alignItems="center" gap={1}>
            <Tooltip title="Refresh History">
              <IconButton
                size="small"
                onClick={fetchTrades}
                disabled={isLoading}
              >
                <Refresh />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        <Box display="flex" gap={2} mb={3} flexWrap="wrap">
          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">
                Total Trades
              </Typography>
              <Typography variant="h6">{stats.totalTrades}</Typography>
            </CardContent>
          </Card>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">
                Successful Trades
              </Typography>
              <Typography variant="h6">{stats.successfulTrades}</Typography>
            </CardContent>
          </Card>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">
                Total Profit
              </Typography>
              <Typography
                variant="h6"
                color={stats.totalProfit >= 0 ? "success.main" : "error.main"}
              >
                {formatCurrency(stats.totalProfit)}
              </Typography>
            </CardContent>
          </Card>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">
                Win Rate
              </Typography>
              <Typography variant="h6">{stats.winRate.toFixed(1)}%</Typography>
            </CardContent>
          </Card>
        </Box>

        {isLoading ? (
          <Box display="flex" justifyContent="center" p={2}>
            <CircularProgress size={24} />
          </Box>
        ) : (
          <TableContainer component={Paper} variant="outlined">
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Time</TableCell>
                  <TableCell>Pair</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell align="right">Amount</TableCell>
                  <TableCell align="right">Price</TableCell>
                  <TableCell align="right">Total</TableCell>
                  <TableCell align="right">Profit</TableCell>
                  <TableCell>Status</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {trades.map((trade) => (
                  <TableRow key={trade.id}>
                    <TableCell>{formatDate(trade.timestamp)}</TableCell>
                    <TableCell>{trade.pair}</TableCell>
                    <TableCell>
                      <Chip
                        size="small"
                        icon={
                          trade.type === "buy" ? (
                            <TrendingUp />
                          ) : (
                            <TrendingDown />
                          )
                        }
                        label={trade.type.toUpperCase()}
                        color={trade.type === "buy" ? "success" : "error"}
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell align="right">{trade.amount}</TableCell>
                    <TableCell align="right">
                      {formatCurrency(trade.price)}
                    </TableCell>
                    <TableCell align="right">
                      {formatCurrency(trade.total)}
                    </TableCell>
                    <TableCell align="right">
                      {trade.profit !== undefined && (
                        <Typography
                          color={
                            trade.profit >= 0 ? "success.main" : "error.main"
                          }
                        >
                          {formatCurrency(trade.profit)}
                        </Typography>
                      )}
                    </TableCell>
                    <TableCell>
                      <Chip
                        size="small"
                        label={trade.status}
                        color={
                          trade.status === "completed"
                            ? "success"
                            : trade.status === "failed"
                            ? "error"
                            : "warning"
                        }
                      />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}

        <Box mt={2}>
          <Alert severity="info" icon={<Info />}>
            Trading history is automatically updated every minute. Click the
            refresh button to update manually.
          </Alert>
        </Box>
      </CardContent>
    </Card>
  );
};

"use client";
import React, { useEffect, useState } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  CircularProgress,
  Chip,
  Grid,
  IconButton,
  Tooltip,
} from "@mui/material";
import {
  Wifi,
  WifiOff,
  AccountBalance,
  Refresh,
  Warning,
} from "@mui/icons-material";
import { useAuth } from "../hooks/useAuth";
import { TradingManager } from "../config/trading";

interface WalletBalance {
  currency: string;
  balance: number;
  usdValue: number;
}

interface TradingStatusProps {
  className?: string;
}

export const TradingStatus: React.FC<TradingStatusProps> = ({ className }) => {
  const { user } = useAuth();
  const [isConnected, setIsConnected] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [walletBalances, setWalletBalances] = useState<WalletBalance[]>([]);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [_error, setError] = useState<string | null>(null);

  const fetchStatus = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Get connection status
      const connectionStatus =
        TradingManager.getInstance().getConnectionStatus();
      setIsConnected(connectionStatus.isConnected);

      if (connectionStatus.isConnected) {
        // Get wallet balances
        const balances = await TradingManager.getInstance().getWalletBalances();
        setWalletBalances(balances);
      } else {
        setError(connectionStatus.lastError || "Connection lost");
      }

      setLastUpdate(new Date());
    } catch (_err) {
      void _err;
      setError(_err instanceof Error ? _err.message : "Failed to fetch status");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 30000); // Update every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const formatBalance = (balance: number) => {
    return new Intl.NumberFormat("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 8,
    }).format(balance);
  };

  const formatUSD = (amount: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(amount);
  };

  if (!user || !["master", "sister"].includes(user.role)) {
    return null;
  }

  return (
    <Card className={className}>
      <CardContent>
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={2}
        >
          <Typography variant="h6" component="h2">
            Trading System Status
          </Typography>
          <Box display="flex" alignItems="center" gap={1}>
            <Chip
              icon={isConnected ? <Wifi /> : <WifiOff />}
              label={isConnected ? "Connected" : "Disconnected"}
              color={isConnected ? "success" : "error"}
              size="small"
            />
            <Tooltip title="Refresh Status">
              <IconButton
                size="small"
                onClick={fetchStatus}
                disabled={isLoading}
              >
                <Refresh />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>

        {isLoading ? (
          <Box display="flex" justifyContent="center" p={2}>
            <CircularProgress size={24} />
          </Box>
        ) : error ? (
          <Box display="flex" alignItems="center" gap={1} color="error.main">
            <Warning fontSize="small" />
            <Typography variant="body2">{error}</Typography>
          </Box>
        ) : (
          <>
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  sm: "1fr 1fr",
                  md: "1fr 1fr 1fr",
                },
                gap: 2,
              }}
            >
              {walletBalances.map((wallet) => (
                <Box key={wallet.currency}>
                  <Card variant="outlined">
                    <CardContent>
                      <Box display="flex" alignItems="center" gap={1} mb={1}>
                        <AccountBalance fontSize="small" />
                        <Typography variant="subtitle2">
                          {wallet.currency}
                        </Typography>
                      </Box>
                      <Typography variant="h6">
                        {formatBalance(wallet.balance)}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        ≈ {formatUSD(wallet.usdValue)}
                      </Typography>
                    </CardContent>
                  </Card>
                </Box>
              ))}
            </Box>

            <Box mt={2}>
              <Typography variant="caption" color="text.secondary">
                Last updated: {lastUpdate.toLocaleTimeString()}
              </Typography>
            </Box>
          </>
        )}
      </CardContent>
    </Card>
  );
};

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Switch } from "@/components/ui/switch";
import {
  User,
  Star,
  Zap,
  Eye,
  Play,
  Download,
  RefreshCw,
  Volume2,
  Sparkles,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { getSessionHeaders } from "../../services/qmoiSession";
import {
  avatarsConfig,
  animationEngines,
  qualityLevels,
  voiceProfiles,
} from "./avatarsConfig";

interface AvatarSelectorProps {
  currentVoiceId?: string;
  onAvatarChange?: (avatarId: string) => void;
  className?: string;
}

export function AvatarSelector({
  currentVoiceId,
  onAvatarChange,
  className,
}: AvatarSelectorProps) {
  const [selectedAvatar, setSelectedAvatar] = useState<string>("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [selectedQuality, setSelectedQuality] = useState<string>("all");
  const [selectedEngine, setSelectedEngine] = useState<string>("all");
  const [autoUpgrade, setAutoUpgrade] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [previewMode, setPreviewMode] = useState(false);
  const { toast } = useToast();

  // Get current voice's default avatar
  const currentVoice = voiceProfiles.find(
    (voice) => voice.id === currentVoiceId,
  );
  const defaultAvatar =
    avatarsConfig.find((avatar) => avatar.voiceProfile === currentVoiceId) ||
    avatarsConfig[0];

  useEffect(() => {
    // Load saved avatar preference or use voice default
    const savedAvatar = localStorage.getItem("qmoi-avatar-preference");
    setSelectedAvatar(savedAvatar || defaultAvatar.id);
  }, [defaultAvatar.id]);

  const handleAvatarChange = async (avatarId: string) => {
    setIsLoading(true);
    try {
      // Save to localStorage
      localStorage.setItem("qmoi-avatar-preference", avatarId);
      setSelectedAvatar(avatarId);

      // Call API to switch avatar
      const _response = await fetch("/api/qmoi/avatars", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "switch", avatarId }),
      });

      if (!response.ok) throw new Error("Failed to switch avatar");

      // Notify parent component
      onAvatarChange?.(avatarId);

      toast({
        title: "Avatar Updated",
        description: `QMOI is now using the ${
          avatarsConfig.find((a) => a.id === avatarId)?.name
        } avatar.`,
      });
    } catch (_e: unknown) {
      console.warn(String(_e));
      toast({
        title: "Error",
        description: "Failed to switch avatar. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpgrade = async (avatarId: string) => {
    setIsLoading(true);
    try {
      const _response = await fetch("/api/qmoi/avatars", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "upgrade", avatarId }),
      });

      if (!response.ok) throw new Error("Failed to upgrade avatar");

      toast({
        title: "Avatar Upgraded",
        description: "Avatar has been successfully upgraded with new features.",
      });
    } catch (_e: unknown) {
      console.warn(String(_e));
      toast({
        title: "Upgrade Error",
        description: "Failed to upgrade avatar. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleEnhance = async (avatarId: string) => {
    setIsLoading(true);
    try {
      const avatar = avatarsConfig.find((a) => a.id === avatarId);
      const _response = await fetch("/api/qmoi/avatars", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({
          action: "enhance",
          avatarId,
          quality: avatar?.qualityLevel,
          engine: avatar?.animationEngine,
        }),
      });

      if (!response.ok) throw new Error("Failed to enhance avatar");

      toast({
        title: "Avatar Enhanced",
        description:
          "Avatar has been enhanced with improved quality and features.",
      });
    } catch (_e: unknown) {
      console.warn(String(_e));
      toast({
        title: "Enhancement Error",
        description: "Failed to enhance avatar. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const getQualityColor = (quality: string) => {
    switch (quality) {
      case "ai-enhanced":
        return "bg-purple-500";
      case "ultra":
        return "bg-blue-500";
      case "enhanced":
        return "bg-green-500";
      default:
        return "bg-gray-500";
    }
  };

  const getEngineColor = (engine: string) => {
    switch (engine) {
      case "eva3d-sadtalker":
        return "bg-purple-500";
      case "gaussian-splatting":
        return "bg-blue-500";
      case "three-js":
        return "bg-green-500";
      case "luma-ai":
        return "bg-orange-500";
      case "pika-labs":
        return "bg-pink-500";
      default:
        return "bg-gray-500";
    }
  };

  const filteredAvatars = avatarsConfig.filter((avatar) => {
    if (selectedCategory !== "all" && avatar.category !== selectedCategory)
      return false;
    if (selectedQuality !== "all" && avatar.qualityLevel !== selectedQuality)
      return false;
    if (selectedEngine !== "all" && avatar.animationEngine !== selectedEngine)
      return false;
    return true;
  });

  const categories = [
    "all",
    ...Array.from(new Set(avatarsConfig.map((a) => a.category))),
  ];
  const qualities = ["all", ...Object.keys(qualityLevels)];
  const engines = ["all", ...Object.keys(animationEngines)];

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <User className="h-5 w-5" />
          Avatar Settings
        </CardTitle>
        <CardDescription>
          Choose QMOI's avatar and customize appearance settings
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <Tabs defaultValue="avatars" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="avatars">Avatars</TabsTrigger>
            <TabsTrigger value="preview">Preview</TabsTrigger>
            <TabsTrigger value="settings">Settings</TabsTrigger>
          </TabsList>

          <TabsContent value="avatars" className="space-y-4">
            {/* Filters */}
            <div className="grid grid-cols-3 gap-2">
              <Select
                value={selectedCategory}
                onValueChange={setSelectedCategory}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((category) => (
                    <SelectItem key={category} value={category}>
                      {category === "all" ? "All Categories" : category}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Select
                value={selectedQuality}
                onValueChange={setSelectedQuality}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Quality" />
                </SelectTrigger>
                <SelectContent>
                  {qualities.map((quality) => (
                    <SelectItem key={quality} value={quality}>
                      {quality === "all"
                        ? "All Qualities"
                        : qualityLevels[quality as keyof typeof qualityLevels]
                            ?.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Select value={selectedEngine} onValueChange={setSelectedEngine}>
                <SelectTrigger>
                  <SelectValue placeholder="Engine" />
                </SelectTrigger>
                <SelectContent>
                  {engines.map((engine) => (
                    <SelectItem key={engine} value={engine}>
                      {engine === "all"
                        ? "All Engines"
                        : animationEngines[
                            engine as keyof typeof animationEngines
                          ]?.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Avatar Grid */}
            <div className="grid gap-4">
              {filteredAvatars.map((avatar) => (
                <div
                  key={avatar.id}
                  className={`flex items-center justify-between p-4 rounded-lg border cursor-pointer transition-all hover:bg-accent ${
                    selectedAvatar === avatar.id
                      ? "border-primary bg-primary/5"
                      : "border-border"
                  }`}
                  onClick={() => handleAvatarChange(avatar.id)}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-gradient-to-br from-blue-400 to-purple-500 rounded-lg flex items-center justify-center">
                      <User className="h-8 w-8 text-white" />
                    </div>

                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{avatar.name}</span>
                        {avatar.isPremium && (
                          <Star className="h-4 w-4 text-yellow-500" />
                        )}
                        {avatar.autoUpgrade && (
                          <RefreshCw className="h-4 w-4 text-blue-500" />
                        )}
                      </div>

                      <p className="text-sm text-muted-foreground">
                        {avatar.description}
                      </p>

                      <div className="flex items-center gap-2 mt-2">
                        <Badge
                          variant="secondary"
                          className={`text-xs ${getQualityColor(
                            avatar.qualityLevel,
                          )}`}
                        >
                          {avatar.qualityLevel}
                        </Badge>
                        <Badge
                          variant="outline"
                          className={`text-xs ${getEngineColor(
                            avatar.animationEngine,
                          )}`}
                        >
                          {animationEngines[avatar.animationEngine]?.name}
                        </Badge>
                        <Badge variant="outline" className="text-xs">
                          {avatar.type}
                        </Badge>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {selectedAvatar === avatar.id && (
                      <div className="w-2 h-2 bg-primary rounded-full" />
                    )}

                    <Button
                      size="sm"
                      variant="outline"
                      onClick={(_e) => {
                        _e.stopPropagation();
                        handleUpgrade(avatar.id);
                      }}
                      disabled={isLoading}
                    >
                      <Download className="h-4 w-4" />
                    </Button>

                    <Button
                      size="sm"
                      variant="outline"
                      onClick={(_e) => {
                        _e.stopPropagation();
                        handleEnhance(avatar.id);
                      }}
                      disabled={isLoading}
                    >
                      <Sparkles className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>

            <div className="flex items-center space-x-2">
              <Switch
                id="auto-upgrade"
                checked={autoUpgrade}
                onCheckedChange={setAutoUpgrade}
              />
              <label htmlFor="auto-upgrade" className="text-sm">
                Auto-upgrade avatars with new features
              </label>
            </div>
          </TabsContent>

          <TabsContent value="preview" className="space-y-4">
            <div className="aspect-video rounded-lg overflow-hidden bg-black">
              {selectedAvatar ? (
                // If avatar provides a previewUrl, show it live in an iframe/video
                (() => {
                  const avatar = avatarsConfig.find(
                    (a) => a.id === selectedAvatar,
                  );
                  const previewUrl =
                    avatar?.previewUrl || avatar?.demoUrl || null;
                  if (previewUrl) {
                    return (
                      <iframe
                        title={`avatar-preview-${selectedAvatar}`}
                        src={`${previewUrl}`}
                        className="w-full h-full border-0"
                        sandbox="allow-scripts allow-same-origin allow-forms"
                      />
                    );
                  }

                  // Fallback static preview box
                  return (
                    <div className="h-full flex items-center justify-center text-white">
                      <div className="text-center">
                        <User className="h-16 w-16 mx-auto mb-4" />
                        <p className="text-lg font-medium">
                          {avatar?.name || "Avatar Preview"}
                        </p>
                        <p className="text-sm opacity-80">
                          Preview unavailable
                        </p>
                      </div>
                    </div>
                  );
                })()
              ) : (
                <div className="h-full flex items-center justify-center text-white">
                  <div className="text-center">
                    <User className="h-16 w-16 mx-auto mb-4" />
                    <p className="text-lg font-medium">No avatar selected</p>
                    <p className="text-sm opacity-80">
                      Choose an avatar to preview
                    </p>
                  </div>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <Button
                onClick={() => setPreviewMode(!previewMode)}
                className="flex items-center gap-2"
              >
                <Eye className="h-4 w-4" />
                {previewMode ? "Stop Preview" : "Start Preview"}
              </Button>

              <Button variant="outline" className="flex items-center gap-2">
                <Play className="h-4 w-4" />
                Demo Animation
              </Button>
            </div>

            <div className="p-3 bg-muted rounded-lg">
              <div className="text-sm text-muted-foreground">
                Current Avatar:{" "}
                <span className="font-medium">
                  {avatarsConfig.find((a) => a.id === selectedAvatar)?.name}
                </span>
              </div>
              <div className="text-sm text-muted-foreground">
                Engine:{" "}
                <span className="font-medium">
                  {
                    animationEngines[
                      avatarsConfig.find((a) => a.id === selectedAvatar)
                        ?.animationEngine || "framer-motion"
                    ]?.name
                  }
                </span>
              </div>
              <div className="text-sm text-muted-foreground">
                Quality:{" "}
                <span className="font-medium">
                  {
                    avatarsConfig.find((a) => a.id === selectedAvatar)
                      ?.qualityLevel
                  }
                </span>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="settings" className="space-y-4">
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium">Animation Quality</label>
                <Select
                  value={selectedQuality}
                  onValueChange={setSelectedQuality}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(qualityLevels).map(([key, level]) => (
                      <SelectItem key={key} value={key}>
                        <div className="flex items-center gap-2">
                          <span>{level.name}</span>
                          {key === "ai-enhanced" && (
                            <Zap className="h-4 w-4 text-purple-500" />
                          )}
                          {key === "ultra" && (
                            <Star className="h-4 w-4 text-blue-500" />
                          )}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground mt-1">
                  {
                    qualityLevels[selectedQuality as keyof typeof qualityLevels]
                      ?.description
                  }
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium">Advanced Settings</label>
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Auto-enhance avatar quality</span>
                    <Switch defaultChecked />
                  </div>
