import React, { useState, useRef } from "react";

const COMMON_COMMANDS = [
  { label: "Build", cmd: "npm run build" },
  { label: "Install", cmd: "npm install" },
  { label: "Test", cmd: "npm test" },
  { label: "Lint", cmd: "npm run lint" },
  { label: "Deploy", cmd: "npm run deploy" },
];

function mask(cmd: string) {
  return /pass|secret|token|key|rm|delete|reset/i.test(cmd) ? "[MASKED]" : cmd;
}

export default function CommandPanel() {
  const [cmd, setCmd] = useState("");
  const [deviceId, setDeviceId] = useState("qcity");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  type HistoryItem = { cmd: string; deviceId: string; ts: number };
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    try {
      return JSON.parse(
        localStorage.getItem("qcity-cmd-history") || "[]"
      ) as HistoryItem[];
    } catch {
      return [];
    }
  });
  const [pinned, setPinned] = useState<string[]>(() => {
    try {
      return JSON.parse(
        localStorage.getItem("qcity-cmd-pinned") || "[]"
      ) as string[];
    } catch {
      return [];
    }
  });
  const [confirm, setConfirm] = useState(false);
  const eventSourceRef = useRef<EventSource | null>(null);

  function runCommand(stream = true) {
    if (/rm|delete|reset/i.test(cmd) && !confirm) {
      setConfirm(true);
      return;
    }
    setLoading(true);
    setOutput("");
    const body = JSON.stringify({ cmd, deviceId, stream });
    const headers = {
      "Content-Type": "application/json",
      "x-qcity-admin-key": localStorage.getItem("qcity-admin-key") || "",
    };
    if (stream) {
      const es = new EventSource(
        `/api/qcity/remote-command?body=${encodeURIComponent(body)}`
      );
      eventSourceRef.current = es;
      es.onmessage = (ev: MessageEvent) => {
        if (ev.data === "[DONE]") {
          es.close();
          setLoading(false);
        } else setOutput((o) => o + String(ev.data));
      };
      es.onerror = (_err: Event) => {
        console.warn(String(_err));
        es.close();
        setLoading(false);
        setOutput((o) => o + "\n[Error]");
      };
    } else {
      fetch("/api/qcity/remote-command", { method: "POST", headers, body })
        .then((r) => r.json())
        .then((_res: unknown) => {
          const _res = res as Record<string, unknown>;
          setOutput(String(_res.output ?? _res.error ?? ""));
          setLoading(false);
        })
        .catch((_e: unknown) => {
          console.warn(String(_e));
          setLoading(false);
          setOutput((o) => o + "\n[Error]");
        });
    }
    const newHistory = [
      { cmd: mask(cmd), deviceId, ts: Date.now() },
      ...history,
    ].slice(0, 10);
    setHistory(newHistory);
    localStorage.setItem("qcity-cmd-history", JSON.stringify(newHistory));
  }

  function clearHistory() {
    setHistory([]);
    localStorage.removeItem("qcity-cmd-history");
    setPinned([]);
    localStorage.removeItem("qcity-cmd-pinned");
  }
  return (
    <div className="p-4 bg-gray-900 text-white rounded shadow-lg">
      <h3 className="font-bold text-cyan-400 mb-2">Remote Command Panel</h3>
      <div className="flex gap-2 mb-2">
        <input
          value={cmd}
          onChange={(_e) => setCmd(_e.target.value)}
          className="flex-1 bg-gray-800 p-2 rounded"
          placeholder="Enter command..."
        />
        <select
          value={deviceId}
          onChange={(_e) => setDeviceId(_e.target.value)}
          className="bg-gray-800 p-2 rounded"
        >
          <option value="qcity">QCity</option>
          {/* Add more devices as needed */}
        </select>
        <button
          onClick={() => runCommand(true)}
          disabled={loading}
          className="bg-cyan-700 px-3 py-1 rounded"
        >
          Run
        </button>
      </div>
      <div className="mb-2">
        {COMMON_COMMANDS.map((c) => (
          <button
            key={c.label}
            onClick={() => setCmd(c.cmd)}
            className="mr-2 px-2 py-1 bg-gray-700 rounded text-sm"
          >
            {c.label}
          </button>
        ))}
      </div>
      <div className="mb-2">
        <span className="font-bold">Pinned:</span>
        {pinned.map((item: string, i: number) => (
          <button
            key={i}
            onClick={() => setCmd(item)}
            className="ml-2 px-2 py-1 bg-cyan-800 rounded text-xs"
          >
            {item}
          </button>
        ))}
      </div>
      <div className="mb-2">
        <span className="font-bold">History:</span>
        {history.map((item: HistoryItem, i: number) => (
          <button
            key={i}
            onClick={() => setCmd(item.cmd)}
            className="ml-2 px-2 py-1 bg-gray-700 rounded text-xs"
          >
            {item.cmd}
          </button>
        ))}
        <button
          onClick={clearHistory}
          className="ml-2 px-2 py-1 bg-red-700 rounded text-xs"
        >
          Clear
        </button>
      </div>
      {confirm && (
        <div className="bg-yellow-900 p-2 rounded mb-2">
          <span>Are you sure you want to run a destructive command?</span>
          <button
            onClick={() => {
              setConfirm(false);
              runCommand();
            }}
            className="ml-2 px-2 py-1 bg-red-700 rounded"
          >
            Yes
          </button>
          <button
            onClick={() => setConfirm(false)}
            className="ml-2 px-2 py-1 bg-gray-700 rounded"
          >
            No
          </button>
        </div>
      )}
      <div
        className="bg-black p-2 rounded h-40 overflow-y-auto text-xs whitespace-pre-wrap"
        aria-live="polite"
      >
        {output}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from "react";

export default function DevicePanel() {
  type Device = {
    id?: string;
    name: string;
    host: string;
    port: number;
    username: string;
    password?: string;
    privateKey?: string;
  };
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(false);
  const [_error, setError] = useState<string>("");
  const [form, setForm] = useState<Device>({
    name: "",
    host: "",
    port: 22,
    username: "",
    password: "",
    privateKey: "",
  });
  const [editing, setEditing] = useState<Device | null>(null);
  const [testResult, setTestResult] = useState("");

  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const fetchDevices = () => {
    setLoading(true);
    fetch("/api/qcity/devices", {
      headers: { Authorization: token ? `Bearer ${token}` : "" },
    })
      .then((r) => r.json())
      .then((data) => setDevices((data.items as Device[]) || []))
      .catch((_e: unknown) => {
        const msg =
          _e && typeof _e === "object" && "message" in _e
            ? String((_e as { message?: unknown }).message)
            : String(_e);
        console.warn(msg);
        setError(msg);
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchDevices();
  }, []);

  const save = () => {
    setLoading(true);
    fetch("/api/qcity/devices", {
      method: editing ? "PUT" : "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token ? `Bearer ${token}` : "",
      },
      body: JSON.stringify(editing ? { ...form, id: editing.id } : form),
    })
      .then(fetchDevices)
      .then(() => {
        setForm({
          name: "",
          host: "",
          port: 22,
          username: "",
          password: "",
          privateKey: "",
        });
        setEditing(null);
      })
      .catch((_e: unknown) => {
        const msg =
          _e && typeof _e === "object" && "message" in _e
            ? String((_e as { message?: unknown }).message)
            : String(_e);
        console.warn(msg);
        setError(msg);
      })
      .finally(() => setLoading(false));
  };

  const del = (id: string) => {
    setLoading(true);
    fetch("/api/qcity/devices", {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
        Authorization: token ? `Bearer ${token}` : "",
      },
      body: JSON.stringify({ id }),
    })
      .then(fetchDevices)
      .catch((_e: unknown) => {
        const msg =
          _e && typeof _e === "object" && "message" in _e
            ? String((_e as { message?: unknown }).message)
            : String(_e);
        console.warn(msg);
        setError(msg);
      })
      .finally(() => setLoading(false));
  };

  const test = (id: string) => {
    setTestResult("Testing...");
    fetch("/api/qcity/devices?action=test", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token ? `Bearer ${token}` : "",
      },
      body: JSON.stringify({ id }),
    })
      .then((r) => r.json())
      .then((_res: unknown) => {
        const data = res as Record<string, unknown>;
        setTestResult(
          data.success ? "Success" : String(data.error ?? "Failed")
        );
      })
      .catch((_e: unknown) => {
        const msg =
          _e && typeof _e === "object" && "message" in _e
            ? String((_e as { message?: unknown }).message)
            : String(_e);
        console.warn(msg);
        setTestResult(msg);
      });
  };

  return (
    <div className="p-4 bg-gray-900 rounded-lg shadow-lg">
      <h2 className="text-xl font-bold mb-4 text-cyan-400">Devices</h2>
      {error && <div className="text-red-400 mb-2">{error}</div>}
      <form
        className="mb-4 flex flex-wrap gap-2"
        onSubmit={(_e) => {
          _e.preventDefault();
          save();
        }}
      >
        <input
          placeholder="Name"
          value={form.name}
          onChange={(_e) => setForm((f) => ({ ...f, name: _e.target.value }))}
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <input
          placeholder="Host"
          value={form.host}
          onChange={(_e) => setForm((f) => ({ ...f, host: _e.target.value }))}
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <input
          placeholder="Port"
          type="number"
          value={form.port}
          onChange={(_e) =>
            setForm((f) => ({ ...f, port: Number(_e.target.value) }))
          }
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <input
          placeholder="Username"
          value={form.username}
          onChange={(_e) =>
            setForm((f) => ({ ...f, username: _e.target.value }))
          }
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <input
          placeholder="Password"
          type="password"
          value={form.password}
          onChange={(_e) =>
            setForm((f) => ({ ...f, password: _e.target.value }))
          }
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <input
          placeholder="Private Key"
          value={form.privateKey}
          onChange={(_e) =>
            setForm((f) => ({ ...f, privateKey: _e.target.value }))
          }
          className="px-2 py-1 rounded bg-gray-800 text-white"
        />
        <button
          type="submit"
          className="px-3 py-1 bg-cyan-700 rounded text-white"
        >
          {editing ? "Update" : "Add"}
        </button>
        {editing && (
          <button
            type="button"
            onClick={() => {
              setEditing(null);
              setForm({
                name: "",
                host: "",
                port: 22,
                username: "",
                password: "",
                privateKey: "",
              });
            }}
            className="px-3 py-1 bg-gray-700 rounded text-white"
          >
            Cancel
          </button>
        )}
      </form>
      {testResult && (
        <div className="text-xs text-cyan-400 mb-2">{testResult}</div>
      )}
      {loading ? (
        <div className="text-gray-400">Loading...</div>
      ) : (
        <table className="w-full text-xs text-left text-gray-300">
          <thead>
            <tr>
              <th>Name</th>
              <th>Host</th>
              <th>Port</th>
              <th>Username</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {devices.map((dev: Device, i: number) => (
              <tr key={i}>
                <td>{dev.name}</td>
                <td>{dev.host}</td>
                <td>{dev.port}</td>
                <td>{dev.username}</td>
                <td>
                  <button
                    onClick={() => {
                      setEditing(dev);
                      setForm(dev);
                    }}
                    className="px-2 py-1 bg-gray-700 rounded text-white mr-1"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => del(dev.id ?? "")}
                    className="px-2 py-1 bg-red-700 rounded text-white mr-1"
                  >
                    Delete
                  </button>
                  <button
                    onClick={() => test(dev.id ?? "")}
                    className="px-2 py-1 bg-cyan-700 rounded text-white"
                  >
                    Test
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

