          <button
            onClick={() => exportToJSON(filteredLogs)}
            style={{
              background: "#222",
              color: "#0f0",
              border: "1px solid #0f0",
              borderRadius: 4,
              padding: "2px 10px",
            }}
          >
            Export JSON
