import React, { useState, useRef } from "react";
import { useAuth } from "../../hooks/useAuth";

// QCity SelfHealPanel: Admin-only panel to trigger and view results of the NPM self-healing script via the backend API. Integrate into Dashboard for enterprise automation and troubleshooting.
// Usage: <SelfHealPanel />
// Only visible to admin/master roles.

const API_URL = "/api/qcity/selfheal-npm";

const SelfHealPanel: React.FC = () => {
  const { user, loading } = useAuth();
  const [running, setRunning] = useState(false);
  const [log, setLog] = useState("");
  const [_error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean | null>(null);
  const [_options, setOptions] = useState({
    forceClean: false,
    essentialsOnly: false,
    diagnosticsOnly: false,
  });
  const [history, setHistory] = useState<Record<string, unknown>[]>(() => {
    try {
      return JSON.parse(
        localStorage.getItem("selfHealHistory") || "[]"
      ) as Record<string, unknown>[];
    } catch {
      return [] as Record<string, unknown>[];
    }
  });
  const eventSourceRef = useRef<EventSource | null>(null);

  const handleSelfHeal = async () => {
    setRunning(true);
    setLog("");
    setError(null);
    setSuccess(null);
    try {
      const token = localStorage.getItem("jwtToken");
      if (!token) {
        setError("No authentication token found");
        setRunning(false);
        return;
      }
      const es = new EventSource(
        API_URL +
          "?token=" +
          encodeURIComponent(token) +
          "&opts=" +
          encodeURIComponent(JSON.stringify(_options))
      );
      eventSourceRef.current = es;
      let logBuffer = "";
      es.onmessage = (_event: MessageEvent) => {
        if (_event.data === "[DONE]") {
          es.close();
          setRunning(false);
          setSuccess(!logBuffer.includes("[ERROR]"));
          const entry: Record<string, unknown> = {
            ts: new Date().toISOString(),
            log: logBuffer,
            _options,
          };
          const newHistory = [entry, ...history].slice(0, 10);
          setHistory(newHistory);
          localStorage.setItem("selfHealHistory", JSON.stringify(newHistory));
        } else {
          logBuffer += String(_event.data) + "\n";
          setLog(logBuffer);
        }
      };
      es.onerror = (_e: Event) => {
        console.warn("SelfHeal event stream error", String(_e));
        setError("Stream error");
        setRunning(false);
        es.close();
      };
    } catch (_err: unknown) {
      console.warn("SelfHeal request failed", String(_err));
      const errMsg =
        typeof _err === "object" && _err && "message" in _err
          ? String((_err as { message?: unknown }).message)
          : "Request failed";
      setError(errMsg);
      setSuccess(false);
      setRunning(false);
    }
  };

  const handleDownload = () => {
    const blob = new Blob([log], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "qcity_npm_selfheal.log";
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleOptionChange = (opt: string) => {
    setOptions((prev) => {
      const key = opt as keyof typeof prev;
      return { ...prev, [key]: !prev[key] };
    });
  };

  const handleClearHistory = () => {
    setHistory([]);
    localStorage.removeItem("selfHealHistory");
  };

  // Scheduling UI (placeholder)
  const handleSchedule = () => {
    alert("Scheduling feature coming soon!");
  };

  if (loading) return <div>Loading...</div>;
  if (!user || user.role !== "master") return null;

  return (
    <div
      style={{
        border: "1px solid #ccc",
        borderRadius: 8,
        padding: 16,
        margin: 16,
      }}
    >
      <h3>QCity NPM Self-Heal</h3>
      <div style={{ marginBottom: 8 }}>
        <label>
          <input
            type="checkbox"
            checked={_options.forceClean}
            onChange={() => handleOptionChange("forceClean")}
          />{" "}
          Force Clean
        </label>
        <label style={{ marginLeft: 12 }}>
          <input
            type="checkbox"
            checked={_options.essentialsOnly}
            onChange={() => handleOptionChange("essentialsOnly")}
          />{" "}
          Essentials Only
        </label>
        <label style={{ marginLeft: 12 }}>
          <input
            type="checkbox"
            checked={_options.diagnosticsOnly}
            onChange={() => handleOptionChange("diagnosticsOnly")}
          />{" "}
          Diagnostics Only
        </label>
      </div>
      <button
        onClick={handleSelfHeal}
        disabled={running}
        style={{ padding: "8px 16px", fontWeight: "bold" }}
      >
        {running ? "Running..." : "Self-Heal NPM"}
      </button>
      <button onClick={handleSchedule} style={{ marginLeft: 8 }}>
        Schedule
      </button>
      <button onClick={handleClearHistory} style={{ marginLeft: 8 }}>
        Clear History
      </button>
      {success && (
        <div style={{ color: "green", marginTop: 8 }}>
          Self-heal completed successfully.
        </div>
      )}
      {error && (
        <div style={{ color: "red", marginTop: 8 }}>Error: {error}</div>
      )}
      {log && (
        <div style={{ marginTop: 16 }}>
          <h4>Log Output</h4>
          <pre
            style={{
              maxHeight: 300,
              overflow: "auto",
              background: "#f9f9f9",
              padding: 8,
            }}
          >
            {log}
          </pre>
          <button onClick={handleDownload} style={{ marginTop: 8 }}>
            Download Log
          </button>
        </div>
      )}
      <div style={{ marginTop: 24 }}>
        <h4>Error/Fix History</h4>
        {history.length === 0 ? (
          <div>No history yet.</div>
        ) : (
          <ul
            style={{
              maxHeight: 120,
              overflow: "auto",
              background: "#f4f4f4",
              padding: 8,
            }}
          >
            {history.map((h: Record<string, unknown>, i) => (
              <li key={i} style={{ marginBottom: 6 }}>
                <b>{String(h.ts)}</b> -{" "}
                <span>{JSON.stringify(h._options)}</span>
                <button
                  style={{ marginLeft: 8 }}
                  onClick={() => setLog(String(h.log))}
                >
                  View Log
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default SelfHealPanel;

import React, { useEffect, useState } from "react";

export interface SessionItem {
  sid: string;
  createdAt?: string;
  expiresAt?: string;
}

export default function SessionPanel() {
  const [sessions, setSessions] = useState<SessionItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [_error, setError] = useState("");
  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const fetchSessions = () => {
    setLoading(true);
    fetch("/api/auth/session", {
      headers: { Authorization: token ? `Bearer ${token}` : "" },
    })
      .then((r) => r.json())
      .then((data: unknown) => {
        const d = data as Record<string, unknown>;
        const items = (d.sessions ?? []) as unknown[];
        setSessions(items as SessionItem[]);
      })
      .catch((_err: unknown) => {
        console.warn("fetch sessions failed", String(_err));
        setError(
          typeof _err === "object" && _err && "message" in _err
            ? String((_err as { message?: unknown }).message)
            : String(_err)
        );
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchSessions();
  }, []);

  const revoke = (sid: string) => {
    setLoading(true);
    fetch("/api/auth/session", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: token ? `Bearer ${token}` : "",
      },
      body: JSON.stringify({ action: "revoke", sid }),
    })
      .then(fetchSessions)
      .catch((_err: unknown) => {
        console.warn("revoke session failed", String(_err));
        setError(
          typeof _err === "object" && _err && "message" in _err
            ? String((_err as { message?: unknown }).message)
            : String(_err)
        );
      })
      .finally(() => setLoading(false));
  };

  return (
    <div className="p-4 bg-gray-900 rounded-lg shadow-lg">
      <h2 className="text-xl font-bold mb-4 text-cyan-400">Sessions</h2>
      {error && <div className="text-red-400 mb-2">{error}</div>}
      {loading ? (
        <div className="text-gray-400">Loading...</div>
      ) : (
        <table className="w-full text-xs text-left text-gray-300">
          <thead>
            <tr>
              <th>Session ID</th>
              <th>Created</th>
              <th>Expires</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {sessions.map((s: SessionItem, i) => (
              <tr key={i}>
                <td>{s.sid}</td>
                <td>{s.createdAt}</td>
                <td>{s.expiresAt}</td>
                <td>
                  <button
                    onClick={() => revoke(s.sid)}
                    className="px-2 py-1 bg-red-700 rounded text-white"
                  >
                    Revoke
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

"use client";
/* eslint-env browser */

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Volume2, Play, Pause, Star, Zap, Mic, Headphones } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { avatarsConfig, voiceProfiles, qualityLevels } from "./avatarsConfig";
import { getSessionHeaders } from "../../services/qmoiSession";

interface VoiceSelectorProps {
  currentAvatarId?: string;
  onVoiceChange?: (voiceId: string) => void;
  className?: string;
}

export function VoiceSelector({
  currentAvatarId,
  onVoiceChange,
  className,
}: VoiceSelectorProps) {
  const [selectedVoice, setSelectedVoice] = useState<string>("");
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState([80]);
  const [quality, setQuality] = useState("enhanced");
  const [autoAdapt, setAutoAdapt] = useState(true);
  const [previewText, setPreviewText] = useState(
    "Hello! I am QMOI, your AI assistant."
  );
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  // Get current avatar's default voice
  const currentAvatar = avatarsConfig.find(
    (avatar) => avatar.id === currentAvatarId
  );
  const defaultVoice = currentAvatar?.voiceProfile || "professional-male";

  useEffect(() => {
    // Load saved voice preference or use avatar default
    const savedVoice = localStorage.getItem("qmoi-voice-preference");
    setSelectedVoice(savedVoice || defaultVoice);
  }, [defaultVoice]);

  const handleVoiceChange = async (voiceId: string) => {
    setIsLoading(true);
    try {
      // Save to localStorage
      localStorage.setItem("qmoi-voice-preference", voiceId);
      setSelectedVoice(voiceId);

      // Call API to switch voice
      const _response = await fetch("/api/qmoi/voice-profiles", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "switch", voiceId }),
      });

      if (!response.ok) throw new Error("Failed to switch voice");

      // Notify parent component
      onVoiceChange?.(voiceId);

      toast({
        title: "Voice Updated",
        description: `QMOI is now using the ${
          voiceProfiles.find((v) => v.id === voiceId)?.name
        } voice.`,
      });
    } catch (_e: unknown) {
      console.warn(String(_e));
      toast({
        title: "Error",
        description: "Failed to switch voice. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async () => {
    if (isPlaying) {
      setIsPlaying(false);
      return;
    }

    setIsPlaying(true);
    try {
      const _response = await fetch("/api/qmoi/voice-preview", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({
          voiceId: selectedVoice,
          text: previewText,
          quality,
          volume: volume[0],
        }),
      });

      if (!response.ok) throw new Error("Failed to play preview");

      // Simulate audio playback
      setTimeout(() => setIsPlaying(false), 3000);
    } catch (_e: unknown) {
      console.warn(String(_e));
      toast({
        title: "Preview Error",
        description: "Could not play voice preview.",
        variant: "destructive",
      });
      setIsPlaying(false);
    }
  };

  const getVoiceQuality = (voiceId: string) => {
    const profile = voiceProfiles.find((v) => v.id === voiceId);
    return profile?.quality || "standard";
  };

  const getQualityColor = (quality: string) => {
    switch (quality) {
      case "ai-enhanced":
        return "bg-purple-500";
      case "ultra":
        return "bg-blue-500";
      case "enhanced":
        return "bg-green-500";
      default:
        return "bg-gray-500";
    }
  };

  const filteredVoices = voiceProfiles.filter((voice) => {
    if (autoAdapt && currentAvatar) {
      // Auto-adapt: show voices that match avatar type
      return voice.type === currentAvatar.type || voice.type === "human";
    }
    return true;
  });

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Mic className="h-5 w-5" />
          Voice Settings
        </CardTitle>
        <CardDescription>
          Choose QMOI's voice and customize audio settings
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <Tabs defaultValue="voices" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="voices">Voices</TabsTrigger>
            <TabsTrigger value="preview">Preview</TabsTrigger>
            <TabsTrigger value="settings">Settings</TabsTrigger>
          </TabsList>

          <TabsContent value="voices" className="space-y-4">
            <div className="grid gap-3">
              {filteredVoices.map((voice) => (
                <div
                  key={voice.id}
                  className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-all hover:bg-accent ${
                    selectedVoice === voice.id
                      ? "border-primary bg-primary/5"
                      : "border-border"
                  }`}
                  onClick={() => handleVoiceChange(voice.id)}
                >
                  <div className="flex items-center gap-3">
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{voice.name}</span>
                        <Badge
                          variant="secondary"
                          className={`text-xs ${getQualityColor(
                            voice.quality
                          )}`}
                        >
                          {voice.quality}
                        </Badge>
                      </div>
                      <span className="text-sm text-muted-foreground capitalize">
                        {voice.type} voice
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {voice.quality === "ai-enhanced" && (
                      <Zap className="h-4 w-4 text-purple-500" />
                    )}
                    {voice.quality === "ultra" && (
                      <Star className="h-4 w-4 text-blue-500" />
                    )}
                    {selectedVoice === voice.id && (
                      <div className="w-2 h-2 bg-primary rounded-full" />
                    )}
                  </div>
                </div>
              ))}
            </div>

            <div className="flex items-center space-x-2">
              <Switch
                id="auto-adapt"
                checked={autoAdapt}
                onCheckedChange={setAutoAdapt}
              />
              <label htmlFor="auto-adapt" className="text-sm">
                Auto-adapt voice to avatar type
              </label>
            </div>
          </TabsContent>

          <TabsContent value="preview" className="space-y-4">
            <div className="space-y-3">
              <label className="text-sm font-medium">Preview Text</label>
              <textarea
                value={previewText}
                onChange={(_e) => setPreviewText(_e.target.value)}
                className="w-full p-3 border rounded-md resize-none"
                rows={3}
                placeholder="Enter text to preview the voice..."
              />
            </div>

            <div className="flex items-center gap-3">
              <Button
                onClick={handlePreview}
                disabled={isLoading}
                className="flex items-center gap-2"
              >
                {isPlaying ? (
                  <Pause className="h-4 w-4" />
                ) : (
                  <Play className="h-4 w-4" />
                )}
                {isPlaying ? "Stop" : "Preview"}
              </Button>

              <div className="flex items-center gap-2 flex-1">
                <Volume2 className="h-4 w-4" />
                <Slider
                  value={volume}
                  onValueChange={setVolume}
                  max={100}
                  step={1}
                  className="flex-1"
                />
                <span className="text-sm w-8">{volume[0]}%</span>
              </div>
            </div>

            <div className="p-3 bg-muted rounded-lg">
              <div className="text-sm text-muted-foreground">
                Current Voice:{" "}
                <span className="font-medium">
                  {voiceProfiles.find((v) => v.id === selectedVoice)?.name}
                </span>
              </div>
              <div className="text-sm text-muted-foreground">
                Quality:{" "}
                <span className="font-medium">
                  {getVoiceQuality(selectedVoice)}
                </span>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="settings" className="space-y-4">
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium">Voice Quality</label>
                <Select value={quality} onValueChange={setQuality}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(qualityLevels).map(([key, level]) => (
                      <SelectItem key={key} value={key}>
                        <div className="flex items-center gap-2">
                          <span>{level.name}</span>
                          {key === "ai-enhanced" && (
                            <Zap className="h-4 w-4 text-purple-500" />
                          )}
                          {key === "ultra" && (
                            <Star className="h-4 w-4 text-blue-500" />
                          )}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground mt-1">
                  {
                    qualityLevels[quality as keyof typeof qualityLevels]
                      ?.description
                  }
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium">Advanced Settings</label>
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Auto-enhance voice quality</span>
                    <Switch defaultChecked />
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm">
                      Adapt to conversation context
                    </span>
                    <Switch defaultChecked />
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Background noise reduction</span>
                    <Switch defaultChecked />
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Emotion detection</span>
                    <Switch defaultChecked />
                  </div>
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>

        {currentAvatar && (
          <div className="p-3 bg-blue-50 dark:bg-blue-950/20 rounded-lg">
            <div className="flex items-center gap-2 text-sm">
              <Headphones className="h-4 w-4 text-blue-500" />
              <span className="font-medium">Avatar Voice Pairing</span>
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              {currentAvatar.name} is optimized for {currentAvatar.voiceProfile}{" "}
              voice
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

