import React, { useState, useEffect } from "react";
import { useToast } from "../../../hooks/use-toast";
import { Loader2 } from "lucide-react";
import { Button } from "../../../components/ui/button";
import { Card } from "../../../components/ui/card";
import { useTimezone } from "../../hooks/useTimezone";

interface WalletManagerProps {
  isMaster?: boolean;
}

interface WalletRequest {
  email: string;
  username: string;
  requestedAt: string;
  status: "pending" | "approved" | "denied";
}

export const WalletManager: React.FC<WalletManagerProps> = ({
  isMaster = false,
}) => {
  const [pendingRequests, setPendingRequests] = useState<WalletRequest[]>([]);
  const [loading, setLoading] = useState(false);
  const [_error, setError] = useState<string | null>(null);
  const [walletRequested, setWalletRequested] = useState(false);
  const { getCurrentTime, currentTimezone } = useTimezone();
  const { toast } = useToast();

  useEffect(() => {
    if (isMaster) {
      fetchPendingRequests();
    }
  }, [isMaster]);

  const fetchPendingRequests = async () => {
    try {
      setLoading(true);
      const _res = await fetch("/api/wallet?pending_wallets=1", {
        headers: { "x-admin-token": localStorage.getItem("adminToken") || "" },
      });
      if (!_res.ok) throw new Error("Failed to fetch pending requests");
      const data = await _res.json();
      setPendingRequests(data as WalletRequest[]);
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      console.warn(msg);
      setError(msg || "Failed to load pending requests");
      toast({
        title: "Error",
        description: "Failed to load pending wallet requests",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleRequestWallet = async () => {
    try {
      setLoading(true);
      setError(null);
      const email = localStorage.getItem("userEmail");
      const username = localStorage.getItem("username");

      if (!email || !username) {
        throw new Error("Please complete your profile first");
      }

      const _res = await fetch("/api/wallet", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-token": localStorage.getItem("adminToken") || "",
        },
        body: JSON.stringify({
          action: "request_wallet",
          email,
          username,
        }),
      });

      const data = await _res.json();

      if (data.status === "pending") {
        setWalletRequested(true);
        toast({
          title: "Success",
          description: "Wallet _request sent to master for approval",
        });
      } else {
        throw new Error(data.error || "Failed to _request wallet");
      }
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      console.warn(msg);
      setError(msg);
      toast({
        title: "Error",
        description: msg,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleApproveWallet = async (email: string) => {
    try {
      setLoading(true);
      setError(null);
      const _res = await fetch("/api/wallet", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-token": localStorage.getItem("adminToken") || "",
          "x-master-token": localStorage.getItem("masterToken") || "",
        },
        body: JSON.stringify({
          action: "approve_wallet",
          email,
        }),
      });

      const data = await _res.json();

      if (data.status === "approved") {
        setPendingRequests((prev) => prev.filter((r) => r.email !== email));
        toast({
          title: "Success",
          description: `Wallet approved for ${email}`,
        });
        await fetchPendingRequests(); // Refresh the list
      } else {
        throw new Error(data.error || "Failed to approve wallet");
      }
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      console.warn(msg);
      setError(msg);
      toast({
        title: "Error",
        description: msg,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Wallet Management</h2>
          <p className="text-gray-500">
            {getCurrentTime()} {currentTimezone.emoji}
          </p>
        </div>
      </div>

      {error && (
        <div
          className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded relative"
          role="alert"
        >
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {!isMaster && (
        <div className="space-y-4">
          <Button
            onClick={handleRequestWallet}
            disabled={loading || walletRequested}
            className="w-full"
          >
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Processing...
              </>
            ) : walletRequested ? (
              "Wallet Request Pending Approval"
            ) : (
              "Request Wallet"
            )}
          </Button>
        </div>
      )}

      {isMaster && (
        <div className="space-y-4">
          <h3 className="text-lg font-semibold">Pending Wallet Requests</h3>
          {loading && (
            <div className="flex items-center justify-center py-4">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          )}
          {!loading && pendingRequests.length === 0 && (
            <p className="text-gray-500 text-center py-4">
              No pending requests
            </p>
          )}
          {pendingRequests.map((_req) => (
            <Card key={_req.email} className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">{_req.username}</p>
                  <p className="text-sm text-gray-500">{_req.email}</p>
                  <p className="text-xs text-gray-400">
                    Requested: {new Date(_req.requestedAt).toLocaleString()}
                  </p>
                </div>
                <Button
                  onClick={() => handleApproveWallet(_req.email)}
                  disabled={loading}
                >
                  {loading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    "Approve"
                  )}
                </Button>
              </div>
            </Card>
          ))}
        </div>
      )}
    </Card>
  );
};

"use client";
import React, { useEffect } from "react";

type Props = {
  children: React.ReactNode;
  attribute?: string;
  defaultTheme?: "light" | "dark" | "system";
  enableSystem?: boolean;
  // When true, temporarily disables CSS transitions during theme changes to avoid flashes
  disableTransitionOnChange?: boolean;
};

export function ThemeProvider({
  children,
  attribute = "data-theme",
  defaultTheme = "system",
  enableSystem = true,
  disableTransitionOnChange = false,
}: Props) {
  useEffect(() => {
    try {
      let theme = defaultTheme;
      if (
        defaultTheme === "system" &&
        enableSystem &&
        typeof window !== "undefined" &&
        window.matchMedia
      ) {
        theme = window.matchMedia("(prefers-color-scheme: dark)").matches
          ? "dark"
          : "light";
      }

      // Optionally disable transitions during theme change to avoid visual flashes
      if (disableTransitionOnChange && typeof document !== "undefined") {
        document.documentElement.classList.add("qmoi-disable-theme-transition");
        // Remove the class after a short delay so normal transitions resume
        setTimeout(() => {
          document.documentElement.classList.remove(
            "qmoi-disable-theme-transition"
          );
        }, 250);
      }

      document.documentElement.setAttribute(attribute, theme as string);
    } catch (_e) {
      // fail silently in tests
    }
  }, [attribute, defaultTheme, enableSystem, disableTransitionOnChange]);

  return <>{children}</>;
}

export default ThemeProvider;

/**
 * Centralized API configuration for production and development environments.
 * Adapters and components import from this file to get the correct base URL and endpoints.
 */

export type Environment = "development" | "staging" | "production" | "local";

export interface ApiConfig {
  environment: Environment;
  baseUrl: string;
  endpoints: {
    media: string;
    verify: string;
    mail: string;
    files: string;
    emergency: string;
    youtube: string;
    health: string;
  };
  timeout: number;
  retries: number;
}

/**
 * Get the current environment (from NEXT_PUBLIC_ENV or default to 'development')
 */
function getCurrentEnvironment(): Environment {
  if (typeof window !== "undefined") {
    // Browser environment
    const env = (globalThis as any).__ENV__ || process.env.NEXT_PUBLIC_ENV;
    return (env as Environment) || "development";
  }
  // Server environment
  return (process.env.NEXT_PUBLIC_ENV as Environment) || "development";
}

/**
 * Configuration per environment
 */
const configMap: Record<Environment, ApiConfig> = {
  local: {
    environment: "local",
    baseUrl: "http://localhost:8000",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 10000,
    retries: 2,
  },
  development: {
    environment: "development",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 10000,
    retries: 2,
  },
  staging: {
    environment: "staging",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "https://staging-api.qmoi.app",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 15000,
    retries: 3,
  },
  production: {
    environment: "production",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "https://api.qmoi.app",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 20000,
    retries: 3,
  },
};

/**
 * Get the API configuration for the current environment
 */
export function getApiConfig(): ApiConfig {
  const env = getCurrentEnvironment();
  const config = configMap[env];
  return {
    ...config,
    baseUrl: process.env.NEXT_PUBLIC_API_URL || config.baseUrl,
  };
}

/**
 * Build a full URL for an API endpoint
 */
export function buildUrl(endpoint: string): string {
  const config = getApiConfig();
  return `${config.baseUrl}${endpoint}`;
}

/**
 * Get a specific endpoint URL
 */
export function getEndpoint(key: keyof ApiConfig["endpoints"]): string {
  const config = getApiConfig();
  return buildUrl(config.endpoints[key]);
}

export default getApiConfig;

